-- ------------------------------------------------------------------- pool
-- Ids come from the question's text, so an unchanged question keeps its id
-- and a student's history stays attached to it.
create temp table pool_seed_questions on commit drop as
select * from jsonb_to_recordset($pool$[
{"id": "2de95c76-9af1-5da4-b079-cea46700e27e", "role": "industrial-engineer", "kind": "role", "difficulty": "easy", "category": "Time study and SMV", "question": "What is SMV, and how is it used in a garment factory?", "key_points": ["Standard minute value: the time a trained operator needs for one operation, with allowances", "The SMV of all operations added together gives the garment SMV", "Used for costing, daily targets, line planning and efficiency"], "source_url": null, "sort_order": 1},
{"id": "46aa16cb-bfd4-5431-9cc1-8c4cdc92073d", "role": "industrial-engineer", "kind": "role", "difficulty": "easy", "category": "Time study and SMV", "question": "How do you do a time study for one sewing operation?", "key_points": ["Break the operation into clear elements", "Time a trained operator over several cycles, with a stopwatch or video", "Rate the operator's pace and add allowances for fatigue and delays", "Tell the operator what you are doing and why"], "source_url": null, "sort_order": 2},
{"id": "770acc12-1c1f-5371-8ef4-8c4533b5add0", "role": "industrial-engineer", "kind": "role", "difficulty": "easy", "category": "Efficiency", "question": "How do you calculate the efficiency of a sewing line?", "key_points": ["Efficiency is minutes produced divided by minutes attended", "Minutes produced: pieces made times the garment SMV", "Minutes attended: operators times working minutes", "Read it with quality: high output with high rework is not good"], "source_url": null, "sort_order": 3},
{"id": "45e91e12-8760-554c-8c01-963668440686", "role": "industrial-engineer", "kind": "role", "difficulty": "easy", "category": "Line balancing", "question": "What is line balancing, and why does a sewing line need it?", "key_points": ["Sharing work so each operator has about the same load", "Stops pieces piling up at one machine while others wait", "Based on the SMV of each operation and each operator's skill"], "source_url": null, "sort_order": 4},
{"id": "3ee1ee77-73e5-5ccc-9079-e179a139f4dc", "role": "industrial-engineer", "kind": "role", "difficulty": "easy", "category": "Lean and layout", "question": "What are the seven wastes in lean, and which have you seen on a production floor?", "key_points": ["Overproduction, waiting, transport, extra processing, inventory, motion and defects", "Gives one real example from a factory visit or internship", "Suggests a simple fix for that waste"], "source_url": null, "sort_order": 5},
{"id": "e57148b0-7613-5835-9239-c8ed16d02170", "role": "industrial-engineer", "kind": "role", "difficulty": "medium", "category": "Line balancing", "question": "One operation on the line is a bottleneck. How do you find it and fix it?", "key_points": ["Look for work piling up in front of one operator, and check cycle times", "Compare its time with the line's target pitch time", "Fixes: split the operation, move a skilled or extra operator, add a helper or attachment", "Check the flow again after the change"], "source_url": null, "sort_order": 6},
{"id": "b2e7a0a2-5cd3-54ec-99b9-983a35ece934", "role": "industrial-engineer", "kind": "role", "difficulty": "medium", "category": "Capacity planning", "question": "How do you work out how many pieces a line can make in a day on a new style?", "key_points": ["Use the number of operators, working minutes, garment SMV and expected efficiency", "Daily target: operators times minutes times efficiency, divided by SMV", "Allow for the learning curve in the first days of a new style", "Agree the plan with production and planning"], "source_url": null, "sort_order": 7},
{"id": "8d7b2a32-9aaf-5efd-8b9e-10724d72f27a", "role": "industrial-engineer", "kind": "role", "difficulty": "medium", "category": "Quality", "question": "Rework on a line is high. How would you find the main causes?", "key_points": ["Collect defect data by operation and type, for example with a check sheet", "Use a Pareto chart to find the few defects that cause most rework", "Go to the line, watch the operation and talk to the operator and supervisor", "Fix the root cause: method, machine, training or material"], "source_url": null, "sort_order": 8},
{"id": "9459b671-2786-5de4-b389-9c465ec34441", "role": "industrial-engineer", "kind": "role", "difficulty": "medium", "category": "Lean and layout", "question": "What is the difference between a straight line layout and a modular layout? When would you use each?", "key_points": ["Straight line: pieces pass along in sequence, good for long runs of one style", "Modular: a small team in a cell, flexible for small orders and frequent changes", "Choose by order size, how often styles change and operator skill"], "source_url": null, "sort_order": 9},
{"id": "ac987c8a-b807-554c-92f6-76421d43f379", "role": "industrial-engineer", "kind": "role", "difficulty": "medium", "category": "People", "question": "Before planning extra shifts, where would you check the legal limits on working hours and overtime?", "key_points": ["The Bangladesh Labour Act 2006 and its amendments set the rules on hours and overtime", "Check the current text and the factory's HR policy, not memory", "Buyer codes of conduct may be stricter than the law", "Plan overtime to stay inside both"], "source_url": "https://bdlaws.minlaw.gov.bd/act-952.html", "sort_order": 10},
{"id": "fb7fc688-6e2e-5ca5-9ce0-15f826400e41", "role": "industrial-engineer", "kind": "role", "difficulty": "hard", "category": "People", "question": "The production manager wants higher targets, but operators say the current target is already too hard. What do you do?", "key_points": ["Check the SMV and the method again with a fresh time study", "Look for real waste to remove before asking people to work faster", "Set targets that a trained operator can meet in normal hours", "Explain the numbers to both sides honestly"], "source_url": null, "sort_order": 11},
{"id": "1c50dc87-1be3-5685-99f7-44cab448b310", "role": "industrial-engineer", "kind": "role", "difficulty": "hard", "category": "Efficiency", "question": "Efficiency on a line dropped this week. How do you find out why, and how do you report it?", "key_points": ["Check the inputs first: attendance, style changes, machine breakdowns, waiting for cut pieces", "Compare hourly output with targets to see when it fell", "Separate one-off causes from ones that keep happening", "Report a short summary with numbers: cause, effect and action"], "source_url": null, "sort_order": 12},
{"id": "06eb3558-68a6-5d75-9b3d-5ba4770fbb5c", "role": "industrial-engineer", "kind": "role", "difficulty": "hard", "category": "Capacity planning", "question": "Planning wants a large order shipped in four weeks. How do you check if the factory can do it?", "key_points": ["Minutes needed: order quantity times SMV", "Compare with the available minutes of lines that can make this style", "Include the learning curve, other orders, holidays and power cuts", "If short, give options: more lines, extra hours within the rules, an approved subcontractor"], "source_url": null, "sort_order": 13},
{"id": "bf9a0e98-7d9d-5143-a9c2-57e9acdd09b7", "role": "industrial-engineer", "kind": "role", "difficulty": "hard", "category": "People", "question": "Many operators are still away for a week after Eid. How do you keep the lines running?", "key_points": ["Plan before Eid: know who is likely to come back late", "Rebalance lines using multi-skilled operators", "Put priority orders on the best-staffed lines", "Tell planning and merchandising the effect on ship dates"], "source_url": null, "sort_order": 14},
{"id": "87e5da8f-e7d2-5629-86da-f07242e3ffb2", "role": "industrial-engineer", "kind": "role", "difficulty": "hard", "category": "Lean and layout", "question": "You join a factory where nobody uses data, and supervisors say 'we have always done it this way'. How do you start improving things?", "key_points": ["Start small: one line and one clear problem", "Show results with simple numbers the supervisors trust", "Involve supervisors and operators in the fix, and give them credit", "Spread what works, step by step"], "source_url": null, "sort_order": 15},
{"id": "31274e90-5e57-5975-949b-f22397c640ab", "role": "software-engineer", "kind": "role", "difficulty": "easy", "category": "Data structures", "question": "What is the difference between an array and a linked list? When would you use each?", "key_points": ["Array: items side by side in memory, fast to read by index", "Linked list: each item points to the next, easy to insert or remove", "Array for reading by position; linked list for many inserts in the middle", "Names the big O cost of reading and inserting for each"], "source_url": null, "sort_order": 1},
{"id": "e355ff47-9ae9-5b6d-b945-47c620a4c469", "role": "software-engineer", "kind": "role", "difficulty": "easy", "category": "Algorithms", "question": "What does big O notation tell you? Explain O(n) and O(log n) with an example.", "key_points": ["How time or memory grows as the input grows", "O(n): one pass through a list, such as finding the largest number", "O(log n): the problem halves each step, such as binary search", "Explains it in plain words, not only symbols"], "source_url": null, "sort_order": 2},
{"id": "17c743b2-ca2a-5c4b-9d7f-7d4b2fadf3af", "role": "software-engineer", "kind": "role", "difficulty": "easy", "category": "OOP", "question": "Explain encapsulation, inheritance and polymorphism with a simple example.", "key_points": ["Encapsulation: hide data behind methods", "Inheritance: one class reuses and extends another", "Polymorphism: one interface, different behaviour", "Uses one small real example, such as different payment types"], "source_url": null, "sort_order": 3},
{"id": "38906fb8-e74a-5fe1-84ba-46b27d897c64", "role": "software-engineer", "kind": "role", "difficulty": "easy", "category": "Databases", "question": "What is the difference between a primary key and a foreign key?", "key_points": ["Primary key: uniquely identifies each row in a table", "Foreign key: points to the primary key of a row in another table", "Together they keep linked data consistent"], "source_url": null, "sort_order": 4},
{"id": "2be3873b-e024-5678-95fb-c02b0562ac75", "role": "software-engineer", "kind": "role", "difficulty": "easy", "category": "Git and delivery", "question": "What is Git, and why do teams work on branches?", "key_points": ["Git tracks every change to the code over time", "Branches let people work without breaking the main code", "Changes are reviewed, then merged", "Small commits with clear messages"], "source_url": null, "sort_order": 5},
{"id": "e7838065-85ed-55e7-8f3f-d923e5ca9315", "role": "software-engineer", "kind": "role", "difficulty": "medium", "category": "Algorithms", "question": "How would you check whether a list has duplicate numbers? Give two ways and compare them.", "key_points": ["Compare every pair: simple, but O(n squared)", "Sort first, then compare neighbours: O(n log n)", "Use a hash set: O(n) time, but extra memory", "Talks through the trade-off out loud, as in a live coding round"], "source_url": null, "sort_order": 6},
{"id": "0feb1309-d055-58a1-b098-41ab47d0a305", "role": "software-engineer", "kind": "role", "difficulty": "medium", "category": "Debugging", "question": "Your solution works for small inputs but times out on large ones in an online judge. What do you do?", "key_points": ["Works out the time complexity of the current solution", "Finds the slow part: nested loops or repeated work", "Picks a better approach: hashing, sorting, two pointers or caching", "Tests edge cases: empty input, one item, the largest input"], "source_url": null, "sort_order": 7},
{"id": "23da84ad-678d-51b5-83f9-9f6c9e200866", "role": "software-engineer", "kind": "role", "difficulty": "medium", "category": "Git and delivery", "question": "What do you look for when you review a teammate's pull request?", "key_points": ["Does it do what the task asks, and does it have tests", "Readable names, small functions, no repeated code", "Edge cases, error handling and security problems", "Comments that are kind, specific and suggest a fix"], "source_url": null, "sort_order": 8},
{"id": "4a7f0600-4f94-545f-bf2a-a9fc6deda96f", "role": "software-engineer", "kind": "role", "difficulty": "medium", "category": "Databases", "question": "When would you choose a SQL database, and when a NoSQL one?", "key_points": ["SQL: structured data with relations and strict consistency, such as orders and payments", "NoSQL: flexible or very large data, such as logs or chat messages", "Most apps start well on SQL", "Choose by the shape of the data and how it is queried"], "source_url": null, "sort_order": 9},
{"id": "56e8b46d-718d-560b-abfc-16e446281b53", "role": "software-engineer", "kind": "role", "difficulty": "medium", "category": "Git and delivery", "question": "What is CI/CD, and what would a simple pipeline for a web app do?", "key_points": ["CI: every push builds the code and runs the tests automatically", "CD: passing builds are deployed to staging, then production", "Steps: lint, test, build, deploy, then a quick check after release", "Catches problems early and makes releases routine"], "source_url": null, "sort_order": 10},
{"id": "9088c46f-2f8f-5e5a-b09d-f531dc6918bd", "role": "software-engineer", "kind": "role", "difficulty": "hard", "category": "System design", "question": "Design a URL shortener. Start simple and explain how it would grow.", "key_points": ["Clarifies needs first: how many links, how long they live", "Basic design: an API, a table from short code to long URL, a redirect", "How codes are made, random or encoded, and how clashes are avoided", "Growth: cache popular links, add read replicas, rate-limit"], "source_url": null, "sort_order": 11},
{"id": "640ff4c2-6b55-560c-a8ea-da7424cacbac", "role": "software-engineer", "kind": "role", "difficulty": "hard", "category": "Debugging", "question": "A bug happens only in production, about once a day, and you cannot reproduce it. How do you approach it?", "key_points": ["Collects evidence: logs, error reports, times, affected users", "Looks for patterns: data, load, time of day, a background job", "Adds logging where you cannot see, then waits for the next case", "Fixes it, adds a test and checks it does not return"], "source_url": null, "sort_order": 12},
{"id": "a8c57ff4-e5d6-5843-b7a7-9dc65876b174", "role": "software-engineer", "kind": "role", "difficulty": "hard", "category": "Teamwork", "question": "You work with an overseas client who is six hours ahead. How do you keep the work moving?", "key_points": ["Agrees a short daily overlap or a written update", "Writes questions and decisions in one shared place", "Plans work so you are not blocked waiting for answers", "Confirms requirements in writing before building"], "source_url": null, "sort_order": 13},
{"id": "57b84528-ec17-58bc-92e2-01041dad8d21", "role": "software-engineer", "kind": "role", "difficulty": "hard", "category": "Data structures", "question": "How would you design a cache that removes the least recently used item when it is full?", "key_points": ["Needs fast lookup and a fast way to update the order of use", "A hash map plus a doubly linked list gives O(1) get and put", "Move an item to the front on each use; remove from the back when full", "Talks through edge cases: capacity of one, updating an existing key"], "source_url": null, "sort_order": 14},
{"id": "3cf33e3d-97aa-5920-bfd7-c10f0d79fa50", "role": "software-engineer", "kind": "role", "difficulty": "hard", "category": "OOP", "question": "You must add a new payment method to old code full of if-else checks. How would you change it safely?", "key_points": ["Writes tests around the current behaviour first", "Refactors to an interface with one class per payment method", "Adds the new method as a new class", "Releases in small steps and watches for errors"], "source_url": null, "sort_order": 15},
{"id": "1b5c7099-9216-5de1-a8e8-f9de85354b87", "role": "backend-developer", "kind": "role", "difficulty": "easy", "category": "APIs", "question": "What is the difference between GET and POST, and when does it matter?", "key_points": ["GET reads data and should not change anything", "POST sends data to create or change something", "GET can be cached and bookmarked, and its parameters show in the URL", "Never put passwords or private data in a GET URL"], "source_url": null, "sort_order": 1},
{"id": "61f5dd47-e0cc-53ee-bcdd-0410f8cd3a06", "role": "backend-developer", "kind": "role", "difficulty": "easy", "category": "Databases", "question": "What does a database index actually do?", "key_points": ["A sorted structure that finds rows without reading the whole table", "Speeds up reads on the indexed columns", "Slows writes a little and uses extra space", "Index the columns you filter, join and sort on"], "source_url": null, "sort_order": 2},
{"id": "e4c0539a-dd1b-5374-9a30-eb2b02bb35eb", "role": "backend-developer", "kind": "role", "difficulty": "easy", "category": "APIs", "question": "A user signs up. Walk me through what your API does, step by step.", "key_points": ["Validates the input: email or phone format, password rules", "Checks the user does not already exist", "Hashes the password and saves the user in one transaction", "Sends a verification message and returns a clear response"], "source_url": null, "sort_order": 3},
{"id": "05889415-380b-5412-ae62-fcb8be480c1d", "role": "backend-developer", "kind": "role", "difficulty": "medium", "category": "Databases", "question": "A query has become slow as the table grew. How do you find out why?", "key_points": ["Runs EXPLAIN to read the query plan", "Looks for full table scans and missing indexes", "Checks for slow joins, sorting, or fetching too many rows", "Fixes it, then measures again with real data sizes"], "source_url": null, "sort_order": 4},
{"id": "41928ded-0dc0-5ad1-82cb-c887d03a407d", "role": "backend-developer", "kind": "role", "difficulty": "medium", "category": "Security", "question": "What is the difference between authentication and authorisation?", "key_points": ["Authentication: checking who you are", "Authorisation: checking what you are allowed to do", "Example: signed in, but not allowed to see another user's orders", "Checks authorisation on the server for every request"], "source_url": null, "sort_order": 5},
{"id": "ae6144ca-2102-5cbb-9247-4c5e7d00c79e", "role": "backend-developer", "kind": "role", "difficulty": "medium", "category": "Concurrency", "question": "Two requests try to book the last seat at the same time. What goes wrong?", "key_points": ["A race condition: both read the seat as free and both book it", "Fix with a database transaction and a row lock", "Or a unique constraint, so the second insert fails", "Tells the second user clearly that the seat is gone"], "source_url": null, "sort_order": 6},
{"id": "6f468104-5f22-5c0b-95b7-1f55ded212bb", "role": "backend-developer", "kind": "role", "difficulty": "hard", "category": "Debugging", "question": "Your API returns 500s for some users and not others. How do you investigate?", "key_points": ["Reads the logs and error traces for the failing requests", "Finds what those users share: data, region, app version, account type", "Reproduces one of their cases in a safe environment", "Fixes it, adds a test and watches the error rate"], "source_url": null, "sort_order": 7},
{"id": "0cfa39f9-8d05-532d-b962-783d5fab5e5b", "role": "backend-developer", "kind": "role", "difficulty": "hard", "category": "Databases", "question": "How would you design the tables behind a food delivery order?", "key_points": ["Tables: customers, restaurants, menu items, orders, order items, riders, payments", "Stores the item price in the order item, because menu prices change", "Keeps an order status history with timestamps", "Indexes and foreign keys for the common lookups"], "source_url": null, "sort_order": 8},
{"id": "1a4663ac-3173-50e3-9c83-077a5f393c12", "role": "backend-developer", "kind": "role", "difficulty": "hard", "category": "Operations", "question": "You must change a column on a ten-million-row table with no downtime. How?", "key_points": ["Adds the new column next to the old one", "Writes to both, then copies old data across in small batches", "Switches reads to the new column, and drops the old one later", "Tests on a copy first, with a rollback plan"], "source_url": null, "sort_order": 9},
{"id": "1209bdeb-ce49-5cb3-bc66-7c21087f97ab", "role": "backend-developer", "kind": "role", "difficulty": "easy", "category": "APIs", "question": "What do the HTTP status code groups 2xx, 4xx and 5xx mean? Give an example of each.", "key_points": ["2xx: it worked, such as 200 OK or 201 Created", "4xx: the client's mistake, such as 400 bad input, 401 not signed in, 404 not found", "5xx: the server failed, such as 500", "The right code lets clients react correctly"], "source_url": null, "sort_order": 10},
{"id": "a79de71c-c47a-5d5e-8ee1-38af10a1a158", "role": "backend-developer", "kind": "role", "difficulty": "easy", "category": "Security", "question": "How should a backend store user passwords?", "key_points": ["Never as plain text or with reversible encryption", "A slow, salted hash such as bcrypt or Argon2", "Compare hashes at sign-in, and limit repeated attempts", "Never write passwords to logs"], "source_url": null, "sort_order": 11},
{"id": "5efd1579-0c68-5a18-a7f4-60bb86412922", "role": "backend-developer", "kind": "role", "difficulty": "medium", "category": "Operations", "question": "SMS OTPs sometimes never reach users. How would you design sign-in so people are not locked out?", "key_points": ["Resend with a short wait and a limit on attempts", "Logs each send and the SMS provider's delivery status", "A second SMS provider or another channel as a fallback", "Clear messages and expiry times for the user"], "source_url": null, "sort_order": 12},
{"id": "25a284d1-82b8-55bf-9f5c-7e9ccfc94f13", "role": "backend-developer", "kind": "role", "difficulty": "medium", "category": "APIs", "question": "What makes an API call idempotent, and why does it matter for payments?", "key_points": ["Calling it twice has the same effect as calling it once", "Clients retry when the network fails, so a payment could be charged twice", "Uses an idempotency key stored with the result", "Returns the stored result for a repeat request"], "source_url": null, "sort_order": 13},
{"id": "ff48aa46-2358-5b60-b38e-610f785ddd57", "role": "backend-developer", "kind": "role", "difficulty": "hard", "category": "Operations", "question": "Traffic jumps tenfold during an Eid sale. How do you keep the API up?", "key_points": ["Load tests before the sale and finds the bottleneck", "Caches read-heavy data and adds the missing indexes", "Queues slow work such as emails and SMS", "Rate-limits, scales out where possible, and watches dashboards live"], "source_url": null, "sort_order": 14},
{"id": "bf0c3732-e8d3-5b8f-87c1-f30786e3c6b1", "role": "backend-developer", "kind": "role", "difficulty": "hard", "category": "Payments", "question": "A payment gateway says a payment succeeded, but your order still shows unpaid. How do you design the system to fix this?", "key_points": ["Handles the gateway's server callback and checks it is genuine", "Makes the callback handler idempotent", "Runs a job that checks pending orders with the gateway and settles them", "Alerts on mismatches and keeps an audit log"], "source_url": null, "sort_order": 15},
{"id": "83d22835-d2f8-5695-a713-e29c90c4cc08", "role": "frontend-developer", "kind": "role", "difficulty": "easy", "category": "Fundamentals", "question": "What happens between typing a URL and the page appearing? Take it as far as you can.", "key_points": ["DNS finds the server's IP address", "A TCP and TLS connection, then an HTTP request", "The server sends HTML; the browser loads the CSS, JavaScript and images it needs", "The browser builds the layout and paints the page"], "source_url": null, "sort_order": 1},
{"id": "8fae97ce-1706-50d0-ba3a-01639a7d9e80", "role": "frontend-developer", "kind": "role", "difficulty": "easy", "category": "Layout", "question": "What is the difference between padding and margin?", "key_points": ["Padding is space inside the border, around the content", "Margin is space outside the border, between elements", "The background fills the padding but not the margin", "Vertical margins can collapse into each other"], "source_url": null, "sort_order": 2},
{"id": "32613f9a-1080-5642-b25f-64dafbfa6756", "role": "frontend-developer", "kind": "role", "difficulty": "easy", "category": "Fundamentals", "question": "You have a list of items from an API. How do you get them onto the page?", "key_points": ["Fetches the data and handles loading and errors", "Loops over the items and renders one element for each", "Gives each item a stable key", "Shows an empty state when the list is empty"], "source_url": null, "sort_order": 3},
{"id": "ef7d2079-46a2-5231-bf29-b3de75a45c70", "role": "frontend-developer", "kind": "role", "difficulty": "medium", "category": "Layout", "question": "A page looks right on your laptop and broken on a 360px phone. How do you find out why?", "key_points": ["Uses the browser's device mode at 360px, then a real phone", "Looks for fixed widths, large images or long words that overflow", "Checks the viewport meta tag and the media queries", "Uses flexible layout: flex, grid, max-width and relative units"], "source_url": null, "sort_order": 4},
{"id": "9fca9390-4b03-57ff-82c7-55f6b70154c1", "role": "frontend-developer", "kind": "role", "difficulty": "medium", "category": "React", "question": "What is the difference between state and props, and what makes a component re-render?", "key_points": ["Props come from the parent and are read-only", "State belongs to the component and changes over time", "It re-renders when its state, its props or a context it uses changes", "A parent re-render also re-renders children unless they are memoised"], "source_url": null, "sort_order": 5},
{"id": "83c7c79c-25e8-54de-a30a-c8f67ea2b0a5", "role": "frontend-developer", "kind": "role", "difficulty": "medium", "category": "Performance", "question": "The page takes six seconds to load on 3G. Where do you look first?", "key_points": ["Measures first, with the network tab and a performance audit", "Large images and big JavaScript bundles", "Too many requests, and nothing cached", "Fonts and scripts that block the first paint"], "source_url": null, "sort_order": 6},
{"id": "9a026709-b121-528c-9c7f-034ce26983ac", "role": "frontend-developer", "kind": "role", "difficulty": "hard", "category": "React", "question": "A form loses what the user typed whenever the parent re-renders. What is happening?", "key_points": ["The input component is recreated, often because it is defined inside the parent", "Or its key changes on every render, so React resets it", "Or the state lives in a component that is being remounted", "Fix: define components outside, keep keys stable, lift state up"], "source_url": null, "sort_order": 7},
{"id": "013b9b5f-b4ab-579d-9cdd-32f441c3d261", "role": "frontend-developer", "kind": "role", "difficulty": "hard", "category": "Accessibility", "question": "How would you make a page usable for somebody using a screen reader?", "key_points": ["Semantic HTML: real buttons, links, headings and lists", "A label for every form field and alt text for images", "Everything works by keyboard, with a visible focus", "Tests with a real screen reader"], "source_url": null, "sort_order": 8},
{"id": "7b2d3a80-c474-5cce-a2e4-94466a4c65eb", "role": "frontend-developer", "kind": "role", "difficulty": "hard", "category": "Architecture", "question": "You need the same data on four screens. How do you avoid fetching it four times?", "key_points": ["Fetches once and keeps it in a shared store or cache", "Or uses a data library that caches and merges repeat requests", "Decides when the data is stale and needs a refresh", "Passes data down or through context instead of fetching on each screen"], "source_url": null, "sort_order": 9},
{"id": "013a2c7e-ce40-51cf-8a75-6072ec042881", "role": "frontend-developer", "kind": "role", "difficulty": "easy", "category": "Fundamentals", "question": "What is the difference between let, const and var in JavaScript?", "key_points": ["The var keyword is function-scoped; let and const are block-scoped", "A const cannot be reassigned, but an object it holds can still change", "Use const by default, and let when the value must change"], "source_url": null, "sort_order": 10},
{"id": "dd572329-a93d-5f43-b8b0-1d8272792cdf", "role": "frontend-developer", "kind": "role", "difficulty": "easy", "category": "Layout", "question": "When would you use flexbox and when would you use CSS grid?", "key_points": ["Flexbox: one direction, a row or a column, such as a nav bar", "Grid: rows and columns together, such as a page layout", "They work well together in one page"], "source_url": null, "sort_order": 11},
{"id": "a633fd28-2972-535a-9e6e-30538f8bbeaa", "role": "frontend-developer", "kind": "role", "difficulty": "medium", "category": "Localisation", "question": "Bangla text shows broken letters on some phones. What could cause it, and how do you fix it?", "key_points": ["The font may not support Bangla joined letters well, or the fallback is poor", "Loads a good Bangla web font, subset to keep it small", "Sets the lang attribute and a proper font stack", "Tests on real low-cost Android phones and several browsers"], "source_url": null, "sort_order": 12},
{"id": "4d764571-5c32-5085-bc5d-28c611e087c9", "role": "frontend-developer", "kind": "role", "difficulty": "medium", "category": "Debugging", "question": "A button works in your desktop browser but does nothing on a customer's phone. How do you debug it?", "key_points": ["Reproduces it on the same device and browser, or an emulator", "Uses remote debugging to read console errors", "Checks for unsupported JavaScript features or another element covering the button", "Fixes it, then adds that device to the test list"], "source_url": null, "sort_order": 13},
{"id": "67827032-d903-5d73-a741-ab018fe14b0b", "role": "frontend-developer", "kind": "role", "difficulty": "hard", "category": "Architecture", "question": "Checkout sends the user to a payment gateway or wallet and back. What can go wrong, and how do you handle it?", "key_points": ["The user may close the app or lose network before coming back", "Never trusts the redirect alone; confirms payment status from the server", "Shows clear pending, success and failed states", "Prevents double payment: disables the button and uses one order ID"], "source_url": null, "sort_order": 14},
{"id": "87788273-8068-5206-90b9-542972877297", "role": "frontend-developer", "kind": "role", "difficulty": "hard", "category": "Performance", "question": "Your React app is large and slow on low-cost phones. How do you make it lighter?", "key_points": ["Measures first with a bundle analyser and a performance audit", "Splits code by route and lazy-loads heavy parts", "Removes or replaces heavy libraries", "Compresses and resizes images, and caches static files"], "source_url": null, "sort_order": 15},
{"id": "ea80a0be-d5a6-5414-b587-0408d1e5e850", "role": "full-stack-developer", "kind": "role", "difficulty": "easy", "category": "Web basics", "question": "What is the difference between server-side rendering and client-side rendering?", "key_points": ["Server-side: the server sends ready HTML, so the first view is fast and search engines read it", "Client-side: the browser builds the page with JavaScript after loading", "Many apps mix both", "Choose by speed on slow phones, search needs and the type of app"], "source_url": null, "sort_order": 1},
{"id": "c0e2439d-7e14-5be6-8992-7aa5319989eb", "role": "full-stack-developer", "kind": "role", "difficulty": "easy", "category": "Web basics", "question": "What is MVC, and how does a framework such as Laravel or Django use the idea?", "key_points": ["Model: data and rules; view: what the user sees; controller: handles the request", "The framework routes a request to code that uses models and returns a view", "Keeps code organised and easier to test"], "source_url": null, "sort_order": 2},
{"id": "e4a9724d-e685-58ce-bc0d-fb7796348ef2", "role": "full-stack-developer", "kind": "role", "difficulty": "easy", "category": "APIs", "question": "What is REST, and how would you design the endpoints for a simple blog?", "key_points": ["Resources are nouns; actions are HTTP methods", "GET and POST on /posts; GET, PUT and DELETE on /posts/{id}", "Consistent JSON and correct status codes"], "source_url": null, "sort_order": 3},
{"id": "c6aeaf9d-e249-5f28-829a-2c030e61c32b", "role": "full-stack-developer", "kind": "role", "difficulty": "easy", "category": "Sign-in and security", "question": "What is the difference between a session cookie and a JWT for keeping a user signed in?", "key_points": ["Session: the server stores the session; the browser keeps only an ID in a cookie", "JWT: a signed token holding user claims, checked without a server lookup", "Sessions are easy to cancel; JWTs need a short expiry or a block list", "Stores tokens where page scripts cannot read them"], "source_url": null, "sort_order": 4},
{"id": "84868f8a-7ec8-53b6-86aa-114cf5f8cfbc", "role": "full-stack-developer", "kind": "role", "difficulty": "easy", "category": "Databases", "question": "What is an ORM, and when would you write raw SQL instead?", "key_points": ["An ORM maps tables to objects in your code", "Fast to build with, and safer from SQL injection by default", "Raw SQL for complex reports, or when performance needs it", "Watches for the N+1 query problem"], "source_url": null, "sort_order": 5},
{"id": "f14a8749-1079-5a90-98b3-eeecfad14b7b", "role": "full-stack-developer", "kind": "role", "difficulty": "medium", "category": "Deployment", "question": "A small firm hosts its PHP site on shared cPanel hosting. How would you deploy an update safely?", "key_points": ["Backs up the files and the database first", "Tests on a staging copy if possible", "Uploads with Git or SFTP, never by editing live files", "Runs migrations, clears caches and checks the site straight after"], "source_url": null, "sort_order": 6},
{"id": "50b6e74d-8147-56f6-85b5-f09daac8a704", "role": "full-stack-developer", "kind": "role", "difficulty": "medium", "category": "Sign-in and security", "question": "How do you protect a web form from SQL injection and cross-site scripting?", "key_points": ["Parameterised queries or the ORM, never SQL built from strings", "Validates input on the server", "Escapes output and uses the framework's templates", "CSRF tokens on forms and a content security policy"], "source_url": null, "sort_order": 7},
{"id": "46c83a36-f503-5e4b-9a4d-f9260997ef38", "role": "full-stack-developer", "kind": "role", "difficulty": "medium", "category": "APIs", "question": "How would you add a local payment gateway to an online shop?", "key_points": ["Creates the order first, then sends the user to the gateway with the order ID", "Confirms payment by the gateway's server callback or a status check, not the redirect", "Handles cancelled, failed and pending payments", "Keeps keys on the server and tests in the gateway's sandbox"], "source_url": null, "sort_order": 8},
{"id": "1e196890-8de8-5300-924a-654289b35eb5", "role": "full-stack-developer", "kind": "role", "difficulty": "medium", "category": "Debugging", "question": "Users say the site is slow, but only on some pages. How do you find out whether the problem is the frontend, the backend or the database?", "key_points": ["Uses the browser's dev tools to find the slow request", "Checks server logs and response times for that endpoint", "Checks the slow query log and adds indexes where needed", "Fixes the biggest cause first and measures again"], "source_url": null, "sort_order": 9},
{"id": "c90e81de-3434-51b5-b5a0-6cddfac8d57c", "role": "full-stack-developer", "kind": "role", "difficulty": "medium", "category": "Frontend", "question": "How do you handle a form on the frontend: validation, errors and loading?", "key_points": ["Validates on the client for speed, and always again on the server", "Shows clear errors next to each field", "Disables submit while sending and shows progress", "Keeps what the user typed if the request fails"], "source_url": null, "sort_order": 10},
{"id": "28a9d42e-8956-5b73-bbd2-8b33144d6bb1", "role": "full-stack-developer", "kind": "role", "difficulty": "hard", "category": "Databases", "question": "Design the database for a small online shop with products, orders and cash on delivery.", "key_points": ["Tables: users, addresses, products, orders, order items, payments", "Stores the price in the order item, because product prices change", "Payment status separate from delivery status, for cash on delivery and returns", "Indexes and foreign keys on the main lookups"], "source_url": null, "sort_order": 11},
{"id": "3e5cfac3-c3dc-59ba-9643-714437130e8c", "role": "full-stack-developer", "kind": "role", "difficulty": "hard", "category": "Deployment", "question": "Your app runs on one server and has gone down twice this month. What would you change?", "key_points": ["Finds the cause first, from logs and monitoring", "Adds health checks, alerts and automatic restarts", "Separates the database, takes regular backups and tests a restore", "Considers a second server or managed hosting as traffic grows"], "source_url": null, "sort_order": 12},
{"id": "1e6558d8-c209-5aa5-9f13-e0fdfdacbc1f", "role": "full-stack-developer", "kind": "role", "difficulty": "hard", "category": "Frontend", "question": "A client wants the site in Bangla and English. How would you build it?", "key_points": ["Keeps all text in translation files, not in the code", "A language switch saved in the URL or the user's settings", "Checks Bangla fonts, dates and numbers", "Plans for longer text and tests both languages"], "source_url": null, "sort_order": 13},
{"id": "5007280f-a11b-588f-b4d8-5d583633d4f4", "role": "full-stack-developer", "kind": "role", "difficulty": "hard", "category": "Sign-in and security", "question": "You find an API key committed to a public Git repository. What do you do?", "key_points": ["Revokes or rotates the key at once", "Checks logs for any misuse", "Removes it from the code and history, and moves it to environment variables", "Adds secret scanning so it cannot happen again"], "source_url": null, "sort_order": 14},
{"id": "5bcc8b33-c786-5eb7-8a0b-8db5ccc6f76d", "role": "full-stack-developer", "kind": "role", "difficulty": "hard", "category": "Debugging", "question": "A feature works on your laptop but breaks after deployment. How do you track it down?", "key_points": ["Compares environments: versions, environment variables, file paths, permissions", "Reads the server logs for the exact error", "Reproduces it with the same settings on staging", "Adds the missing step to the deployment checklist"], "source_url": null, "sort_order": 15},
{"id": "ebad30ff-7af4-50f4-be56-6f74aa0579fb", "role": "it-support-specialist", "kind": "role", "difficulty": "easy", "category": "Hardware", "question": "A computer will not turn on. What do you check, and in what order?", "key_points": ["Power: the socket, the cable, the UPS or IPS, the power strip", "Signs of life: lights, fans, beeps", "Inside: RAM seated, power supply, loose cables", "Explains what was found and what happens next"], "source_url": null, "sort_order": 1},
{"id": "aa79598e-5930-5fc6-b397-266c7848ece4", "role": "it-support-specialist", "kind": "role", "difficulty": "easy", "category": "Networking basics", "question": "What is an IP address, and how do you find one on a Windows PC?", "key_points": ["A number that identifies a device on a network", "The ipconfig command, or the network settings screen", "Private addresses inside the office, a public one from the ISP", "DHCP gives out addresses automatically"], "source_url": null, "sort_order": 2},
{"id": "7bde939f-fac1-5c12-a37c-230bbab1d8e0", "role": "it-support-specialist", "kind": "role", "difficulty": "easy", "category": "Operating systems", "question": "A user says their computer is very slow. What do you check first?", "key_points": ["Asks what changed, and when it is slow", "Task manager: CPU, memory and disk use", "Startup programs, low disk space, malware, updates running", "Hardware: an old hard disk, where an SSD may help"], "source_url": null, "sort_order": 3},
{"id": "de103d50-aeb4-51ca-9d85-531b0b72d093", "role": "it-support-specialist", "kind": "role", "difficulty": "easy", "category": "Accounts and email", "question": "A staff member forgot their email password. How do you reset it safely?", "key_points": ["Confirms who they are, using the agreed process", "Resets it from the admin console with a temporary password", "Asks them to change it at first sign-in and turn on two-step verification", "Logs the request"], "source_url": null, "sort_order": 4},
{"id": "c4f80af0-8864-5e14-aab6-4d18f11c3775", "role": "it-support-specialist", "kind": "role", "difficulty": "easy", "category": "Security habits", "question": "What is phishing, and how do you teach staff to spot it?", "key_points": ["Fake messages that try to steal passwords or money", "Signs: an urgent tone, an odd sender, unexpected links or attachments", "Check by calling the person on a known number", "Report it to IT, and never feel bad for asking"], "source_url": null, "sort_order": 5},
{"id": "8c1be315-17d7-5f3d-aa26-4720ccb48ebb", "role": "it-support-specialist", "kind": "role", "difficulty": "medium", "category": "Hardware", "question": "Power cuts keep damaging office computers. What would you set up?", "key_points": ["A UPS for each important PC, big enough for a safe shutdown", "Checks that the IPS or generator switchover does not cause spikes", "Surge protection and proper earthing", "Auto-save turned on, and staff saving often"], "source_url": null, "sort_order": 6},
{"id": "1b89f201-c541-5f7c-9514-a1031ea9937e", "role": "it-support-specialist", "kind": "role", "difficulty": "medium", "category": "Networking basics", "question": "The office internet is down. How do you find the cause?", "key_points": ["Checks whether it is one PC or everyone", "Checks the router and switch lights, and restarts in the right order", "Pings the router, then a public address, to see where it stops", "Calls the ISP with clear facts, and moves to a backup link if there is one"], "source_url": null, "sort_order": 7},
{"id": "8b2a5d10-aca0-5ab1-994b-0b7fedbb3418", "role": "it-support-specialist", "kind": "role", "difficulty": "medium", "category": "Backup", "question": "How would you set up backups for a small office?", "key_points": ["The 3-2-1 idea: three copies, on two kinds of storage, one off-site", "Automatic backups that keep several versions", "Regular test restores", "Covers email and shared drives, not only PCs"], "source_url": null, "sort_order": 8},
{"id": "7fdf5572-8716-5c3f-b2e1-ada08d962bd2", "role": "it-support-specialist", "kind": "role", "difficulty": "medium", "category": "User support", "question": "A manager who is not technical wants to know why their files were lost. How do you explain it?", "key_points": ["Short, plain words in Bangla or English, without jargon", "What happened, what was recovered, and what is still lost", "What will change so it does not happen again", "Checks they understood, without blaming anyone"], "source_url": null, "sort_order": 9},
{"id": "6a1e95d0-bed6-5bc0-8fc0-25fcddd2654e", "role": "it-support-specialist", "kind": "role", "difficulty": "medium", "category": "Security habits", "question": "Staff keep installing cracked software on office computers. What are the risks, and what do you do?", "key_points": ["Cracked software often carries malware and gets no security updates", "It brings legal and licence risk to the company", "Removes admin rights from everyday user accounts", "Offers licensed or free open-source options and explains why"], "source_url": null, "sort_order": 10},
{"id": "7b6eee60-561f-5fe4-8c2a-dec135473158", "role": "it-support-specialist", "kind": "role", "difficulty": "hard", "category": "Security habits", "question": "Several PCs show a message that files are locked and someone wants payment. What do you do first?", "key_points": ["Disconnects the affected PCs from the network at once", "Does not pay; reports to management", "Finds how it spread and checks the backups are safe", "Restores from clean backups and closes the gap"], "source_url": null, "sort_order": 11},
{"id": "b3457dce-ab51-58a1-8ce9-b450657ae2bc", "role": "it-support-specialist", "kind": "role", "difficulty": "hard", "category": "User support", "question": "Three people ask for urgent help at the same time, including your manager. How do you decide the order?", "key_points": ["Judges by impact: how many people are blocked, and how badly", "Does quick fixes first if they free people fast", "Tells each person when you will reach them", "Logs every request so nothing is forgotten"], "source_url": null, "sort_order": 12},
{"id": "8cc121d1-bd96-59a6-9188-86b471adb3ed", "role": "it-support-specialist", "kind": "role", "difficulty": "hard", "category": "Networking basics", "question": "Wi-Fi in a large office is slow in some rooms. How would you find and fix the problem?", "key_points": ["Maps signal strength room by room", "Checks for channel clashes with nearby networks", "Moves or adds access points, and wires fixed PCs", "Checks whether a few users take most of the bandwidth"], "source_url": null, "sort_order": 13},
{"id": "15147d5b-b34d-5c3f-9f46-bd740d2a8bd7", "role": "it-support-specialist", "kind": "role", "difficulty": "hard", "category": "Accounts and email", "question": "A staff member leaves the company today. What do you do with their accounts and devices?", "key_points": ["Disables accounts the same day and changes shared passwords", "Moves their email and files to the manager", "Collects laptops, phones and access cards", "Follows a written checklist and logs it"], "source_url": null, "sort_order": 14},
{"id": "500f92d2-ced3-505c-a36e-3ae6f1ad113b", "role": "it-support-specialist", "kind": "role", "difficulty": "hard", "category": "Backup", "question": "A server's disk is failing and the last backup is a week old. What do you do?", "key_points": ["Copies the most important data now, before the disk gets worse", "Tells users and management what may be lost", "Replaces the disk and restores", "Fixes the backup schedule so it runs daily and is checked"], "source_url": null, "sort_order": 15},
{"id": "87bd8b18-16ae-53fa-a91e-628e50d5e578", "role": "mobile-app-developer", "kind": "role", "difficulty": "easy", "category": "Language basics", "question": "What is the main thread, and why must slow work stay off it?", "key_points": ["The main thread draws the screen and handles taps", "Slow work there freezes the app or causes an 'app not responding' error", "Network, disk and heavy work go to async code or background threads"], "source_url": null, "sort_order": 1},
{"id": "c7c6c053-8c09-5f1c-9b64-682027f56ec9", "role": "mobile-app-developer", "kind": "role", "difficulty": "easy", "category": "State", "question": "What is the app lifecycle, and why does it matter?", "key_points": ["The system creates, pauses, resumes and destroys screens and apps", "Saves what the user typed before the app goes to the background", "Releases the camera, location and similar resources when paused", "Low-RAM phones close background apps often"], "source_url": null, "sort_order": 2},
{"id": "cfbe7cff-5fb2-5576-b9e2-c0ce27f0b5b5", "role": "mobile-app-developer", "kind": "role", "difficulty": "easy", "category": "Networking", "question": "How does your app call a REST API and show the result?", "key_points": ["Makes the call with async code, off the main thread", "Parses JSON into typed models", "Shows loading, success, empty and error states", "Handles timeouts and no network"], "source_url": null, "sort_order": 3},
{"id": "2a009f4b-23f6-5624-abf7-dfdaecb77137", "role": "mobile-app-developer", "kind": "role", "difficulty": "easy", "category": "Offline storage", "question": "What options do you have for storing data on the phone?", "key_points": ["Key-value storage for small settings", "A local database such as SQLite for structured data", "Files for images and documents", "Secure storage for tokens, never plain settings"], "source_url": null, "sort_order": 4},
{"id": "58cc6088-6c1e-5ed1-894d-834e7ceaac42", "role": "mobile-app-developer", "kind": "role", "difficulty": "easy", "category": "Release", "question": "What steps are needed to publish an Android app on Google's app store?", "key_points": ["Signs the release build with a key that is kept safe", "Prepares the listing: text, screenshots and a privacy policy", "Completes the content rating and data safety forms", "Releases to a test track first, then rolls out in stages"], "source_url": null, "sort_order": 5},
{"id": "5e3e92ba-2aa3-50b3-ab86-181a0a4736f3", "role": "mobile-app-developer", "kind": "role", "difficulty": "medium", "category": "Offline storage", "question": "Users often lose network in the middle of a form. How would you make the app work offline?", "key_points": ["Saves the action on the phone first", "Queues it and syncs when the network returns", "Gives each action an ID so a retry does not create a duplicate", "Shows the user what is waiting to sync"], "source_url": null, "sort_order": 6},
{"id": "aadbaaf5-cb61-5acd-9af0-32f35c702931", "role": "mobile-app-developer", "kind": "role", "difficulty": "medium", "category": "Performance", "question": "The app is slow and crashes on phones with 2 GB of RAM. Where do you look?", "key_points": ["Profiles memory and frame times on a real low-end phone", "Large images: resize and cache them", "Long lists: build items lazily", "Leaks: listeners and controllers that are never disposed"], "source_url": null, "sort_order": 7},
{"id": "8c275544-b064-58a9-9c6e-86ffd9ede50b", "role": "mobile-app-developer", "kind": "role", "difficulty": "medium", "category": "Performance", "question": "Many of your users buy small prepaid data packs. How do you keep the app download small?", "key_points": ["Measures the size and finds the biggest parts", "Compresses images and removes unused assets and libraries", "Uses app bundles so each phone gets only what it needs", "Downloads large content later, on Wi-Fi if the user chooses"], "source_url": null, "sort_order": 8},
{"id": "b23805b8-4970-5a36-976e-418e2ae00e5a", "role": "mobile-app-developer", "kind": "role", "difficulty": "medium", "category": "Networking", "question": "How would you build SMS OTP sign-in in the app?", "key_points": ["Requests the OTP, shows a timer and allows a resend after a wait", "Uses the platform's SMS autofill where it is available", "Handles wrong codes, expiry and network errors clearly", "Never logs the OTP"], "source_url": null, "sort_order": 9},
{"id": "ad210cb1-60f5-558f-98d0-712714e0c6f6", "role": "mobile-app-developer", "kind": "role", "difficulty": "medium", "category": "State", "question": "How do you manage state that many screens share, such as the signed-in user?", "key_points": ["One source of truth in a state management approach such as Provider, Riverpod or Bloc", "Screens listen and rebuild when it changes", "Business logic stays out of the widgets", "The logic is tested without the UI"], "source_url": null, "sort_order": 10},
{"id": "c5ff6f43-8e7d-55c8-b35d-f00abfe332ad", "role": "mobile-app-developer", "kind": "role", "difficulty": "hard", "category": "Debugging", "question": "Crash reports show a crash only on one older Android version. How do you fix it?", "key_points": ["Reads the stack trace and the device details", "Reproduces it on an emulator or a phone with that version", "Checks APIs or permissions that work differently on that version", "Adds a guard or fallback, and a test"], "source_url": null, "sort_order": 11},
{"id": "d8a5ca15-6a41-556b-a7b1-b41e4e95f27d", "role": "mobile-app-developer", "kind": "role", "difficulty": "hard", "category": "Release", "question": "A release has a serious bug and is already rolling out. What do you do?", "key_points": ["Halts the staged rollout at once", "Checks how many users are affected and how badly", "Fixes, tests and releases a new version quickly", "Turns the feature off with a remote switch if there is one"], "source_url": null, "sort_order": 12},
{"id": "73559f79-1053-5ee4-bc70-f4e89f2a9aed", "role": "mobile-app-developer", "kind": "role", "difficulty": "hard", "category": "Offline storage", "question": "Two devices edit the same record offline and both sync later. How do you resolve the conflict?", "key_points": ["Detects it with versions or timestamps", "Chooses a rule: last write wins, merge the fields, or ask the user", "Keeps important changes instead of silently losing them", "Explains the rule to the team and tests it"], "source_url": null, "sort_order": 13},
{"id": "4f390b4e-70f2-51bd-95dc-1c49d3511403", "role": "mobile-app-developer", "kind": "role", "difficulty": "hard", "category": "Networking", "question": "During load shedding your users switch between weak mobile data and Wi-Fi. How do you design network calls?", "key_points": ["Timeouts, and retries with a growing wait", "Caches recent data so screens still show something", "Makes every write safe to retry", "Tells the user clearly when they are offline"], "source_url": null, "sort_order": 14},
{"id": "5a382fbc-077a-52d0-9449-2b044fd59a6a", "role": "mobile-app-developer", "kind": "role", "difficulty": "hard", "category": "Performance", "question": "A list of thousands of items stutters when scrolling. How do you find and fix the cause?", "key_points": ["Profiles frames to see the build or paint cost", "Uses lazy builders and fixed item heights where possible", "Avoids rebuilding the whole list for small changes", "Loads images at the size shown, and caches them"], "source_url": null, "sort_order": 15},
{"id": "0f25efc7-f376-58ea-b0c5-e1ca1e0cd629", "role": "network-engineer", "kind": "role", "difficulty": "easy", "category": "OSI and TCP/IP", "question": "Name the layers of the OSI model and give one example for each.", "key_points": ["Physical, data link, network, transport, session, presentation, application", "Examples: cable, Ethernet and MAC addresses, IP, TCP and UDP, TLS, HTTP", "Says where switches and routers work"], "source_url": null, "sort_order": 1},
{"id": "3de25732-8277-5f76-844e-698b8d64d71b", "role": "network-engineer", "kind": "role", "difficulty": "easy", "category": "OSI and TCP/IP", "question": "What is the difference between TCP and UDP? Give a use for each.", "key_points": ["TCP: a connection with ordered, reliable delivery, such as web pages", "UDP: no connection, faster, may lose packets, such as voice, video and DNS", "Choose by whether speed or reliability matters more"], "source_url": null, "sort_order": 2},
{"id": "7c420fc2-ccb3-5780-a39e-0a3a57feb9fe", "role": "network-engineer", "kind": "role", "difficulty": "easy", "category": "Subnetting", "question": "How many usable hosts are in a /26 network, and why?", "key_points": ["A /26 leaves 6 host bits, so 64 addresses", "Two are reserved, network and broadcast, leaving 62 usable", "Shows the method, not only the answer"], "source_url": null, "sort_order": 3},
{"id": "9b87d98d-9533-5456-8d2b-741a80c0148a", "role": "network-engineer", "kind": "role", "difficulty": "easy", "category": "Switching and VLANs", "question": "What is a VLAN, and why would an office use one?", "key_points": ["Splits one physical switch into separate networks", "Separates groups such as staff, guests and cameras", "Better security and less broadcast traffic", "Trunk ports carry several VLANs between switches"], "source_url": null, "sort_order": 4},
{"id": "f8eabb10-b8bb-522f-b8ed-eb51b8a9ce57", "role": "network-engineer", "kind": "role", "difficulty": "easy", "category": "Routing", "question": "What is the difference between static and dynamic routing?", "key_points": ["Static: routes entered by hand, simple for small networks", "Dynamic: routers share routes with a protocol such as OSPF or BGP", "Dynamic routing adapts when a link fails", "Many networks use both"], "source_url": null, "sort_order": 5},
{"id": "20b91287-0f71-5a26-85d6-f7829220705f", "role": "network-engineer", "kind": "role", "difficulty": "medium", "category": "Troubleshooting", "question": "A home customer of your ISP says the internet is slow. How do you troubleshoot?", "key_points": ["Checks the line, the signal and the router at their end", "Checks the link and port use on your side for congestion", "Tests speed and ping to local and international sites", "Explains the result simply and logs the ticket"], "source_url": null, "sort_order": 6},
{"id": "6b22cda5-611f-543d-a6e4-523a7888623a", "role": "network-engineer", "kind": "role", "difficulty": "medium", "category": "Routing", "question": "What is NAT, and why do ISPs and offices use it?", "key_points": ["Maps many private addresses to one or a few public ones", "Saves scarce IPv4 addresses", "Carrier-grade NAT at an ISP can break some games and remote access", "IPv6 removes much of the need for it"], "source_url": null, "sort_order": 7},
{"id": "4dca472a-e728-54cd-b8de-a1296fd9c94f", "role": "network-engineer", "kind": "role", "difficulty": "medium", "category": "Firewalls and security", "question": "How would you set up firewall rules for a small office?", "key_points": ["Denies by default, then allows only what is needed", "Separates guest Wi-Fi from staff and servers", "Allows remote access only through a VPN", "Logs, reviews and documents every rule"], "source_url": null, "sort_order": 8},
{"id": "6b07e7d8-dec8-5a1a-894e-91bc8ee84d46", "role": "network-engineer", "kind": "role", "difficulty": "medium", "category": "Switching and VLANs", "question": "Users in one VLAN cannot reach a server in another VLAN. How do you find the problem?", "key_points": ["Checks the switch ports and the VLAN tags", "Checks the trunk allows both VLANs", "Checks inter-VLAN routing and the gateway on each device", "Checks firewall rules or access lists between the VLANs"], "source_url": null, "sort_order": 9},
{"id": "7566ec2a-db99-55da-960c-d0759016f396", "role": "network-engineer", "kind": "role", "difficulty": "medium", "category": "ISP operations", "question": "Internet traffic passes through several licensed layers before it reaches a home user in Bangladesh. Explain the path, and where you would check the current licence types.", "key_points": ["International capacity comes in through submarine cables and cross-border fibre", "Nationwide transmission networks carry it across the country to ISPs", "BTRC licenses each layer, and the licence types change over time", "Check BTRC's current list instead of relying on old licence names"], "source_url": "https://btrc.gov.bd/", "sort_order": 10},
{"id": "7292b8dc-32c0-5928-80be-fba87dbbccbd", "role": "network-engineer", "kind": "role", "difficulty": "hard", "category": "Troubleshooting", "question": "A fibre cut takes down your main upstream link at night. What do you do?", "key_points": ["Confirms the fault and moves traffic to the backup link", "Tells customers clearly what is affected and when a fix is expected", "Works with the fibre provider on the location and repair time", "Reviews afterwards: was the backup big enough, and on a different route"], "source_url": null, "sort_order": 11},
{"id": "d0328d55-2862-5dda-96e7-9f26e373eeed", "role": "network-engineer", "kind": "role", "difficulty": "hard", "category": "Firewalls and security", "question": "Your network is hit by a DDoS attack. What steps do you take?", "key_points": ["Identifies the target and the type of traffic", "Filters or rate-limits at the edge, and asks the upstream provider to help", "Protects the most important services first", "Writes up what happened and improves the defences"], "source_url": null, "sort_order": 12},
{"id": "527a780b-667b-5c02-9813-05179a1c1a44", "role": "network-engineer", "kind": "role", "difficulty": "hard", "category": "Firewalls and security", "question": "You see many failed sign-in attempts on an edge router from unknown addresses. What do you do?", "key_points": ["Blocks the sources and limits management access to trusted addresses or a VPN", "Removes default usernames and uses strong passwords or keys", "Updates the router firmware", "Checks the logs for any sign-in that succeeded"], "source_url": null, "sort_order": 13},
{"id": "c14e891c-cada-5c27-98e6-7f91cfbd6aa6", "role": "network-engineer", "kind": "role", "difficulty": "hard", "category": "Switching and VLANs", "question": "Design the network for a new three-floor office with about a hundred staff, guest Wi-Fi and CCTV.", "key_points": ["Core and access switches, with VLANs for staff, guests and CCTV", "Two internet links from different providers, with failover", "UPS power for network equipment, given power cuts", "Documented addressing, with room to grow"], "source_url": null, "sort_order": 14},
{"id": "d8a87f59-a4de-55df-87df-1b7ea40400d5", "role": "network-engineer", "kind": "role", "difficulty": "hard", "category": "Troubleshooting", "question": "How would you find out about a network problem before customers call you?", "key_points": ["Monitors link status, bandwidth, latency and packet loss", "Watches device CPU, memory and temperature", "Uses SNMP-based tools with alerts to the on-call engineer", "Keeps history to spot trends before they become outages"], "source_url": null, "sort_order": 15},
{"id": "1cc97999-4c2f-5c08-8efc-946c9776aad9", "role": "qa-engineer", "kind": "role", "difficulty": "easy", "category": "Fundamentals", "question": "What is the difference between a bug and a feature request?", "key_points": ["A bug: the product does not do what it was meant to", "A feature request: asking for something it was never meant to do", "The requirement or spec decides which one it is", "Both are logged, but they go to different queues"], "source_url": null, "sort_order": 1},
{"id": "2ad3da54-9bc0-5e35-9d75-f99be0f0f6a4", "role": "qa-engineer", "kind": "role", "difficulty": "easy", "category": "Test design", "question": "How would you test a login form?", "key_points": ["Valid and invalid input: right and wrong password, empty fields", "Edge cases: long input, spaces, Bangla characters, copy and paste", "Security: hidden password, lockout after many tries, no hint about which field was wrong", "Usability: clear errors, works on mobile and with the keyboard"], "source_url": null, "sort_order": 2},
{"id": "1d78a948-7f90-5143-995c-4ec853f1cf81", "role": "qa-engineer", "kind": "role", "difficulty": "easy", "category": "Bug reports", "question": "What goes into a bug report that a developer can actually act on?", "key_points": ["A short, clear title", "Exact steps to reproduce, with the test data", "Expected result and actual result", "Device, version, screenshots or video, and logs"], "source_url": null, "sort_order": 3},
{"id": "b70932da-5e80-52b3-a1d2-a114a51584a4", "role": "qa-engineer", "kind": "role", "difficulty": "medium", "category": "Mobile testing", "question": "A bug appears on one phone and not another. How do you narrow it down?", "key_points": ["Compares the phones: OS version, screen size, RAM, app or browser version", "Tries similar phones to find the pattern", "Checks settings: language, font size, battery saver, permissions", "Collects logs from the failing phone"], "source_url": null, "sort_order": 4},
{"id": "03d3d8ba-7696-58c6-9c53-87812c32e9d1", "role": "qa-engineer", "kind": "role", "difficulty": "medium", "category": "Automation", "question": "When do you automate a test and when do you not bother?", "key_points": ["Automates tests that run often and are stable, such as regression and smoke tests", "Does not automate features that change every week", "Keeps manual testing for look and feel, and for exploring", "Compares the time to build and maintain with the time saved"], "source_url": null, "sort_order": 5},
{"id": "2930501a-7d73-53e6-8913-1a50debe7cab", "role": "qa-engineer", "kind": "role", "difficulty": "medium", "category": "Release risk", "question": "You have two hours before a release. What do you test?", "key_points": ["The main user journeys: sign-up, sign-in, payment, the core feature", "What changed in this release and what it touches", "The fixed bugs, to confirm they are fixed", "Tells the team clearly what was not tested"], "source_url": null, "sort_order": 6},
{"id": "2f17bda4-4fe3-5e00-96cd-47469b105292", "role": "qa-engineer", "kind": "role", "difficulty": "hard", "category": "Automation", "question": "A test passes on your machine and fails in CI. How do you investigate?", "key_points": ["Compares environments: versions, data, time zone, screen size, network", "Looks for timing problems and tests that depend on each other", "Reads the CI logs, screenshots and other artefacts", "Runs the same command locally in a clean setup"], "source_url": null, "sort_order": 7},
{"id": "1d0b196c-261a-5f70-aa82-d32011f5c553", "role": "qa-engineer", "kind": "role", "difficulty": "hard", "category": "Performance", "question": "How would you test something that only breaks under load?", "key_points": ["Uses a load testing tool to simulate many users at once", "Ramps up slowly and watches response time, errors and resources", "Tests in an environment like production, with realistic data", "Finds the breaking point and the first part that fails"], "source_url": null, "sort_order": 8},
{"id": "01352b91-68ea-5c82-a7b5-dc0b4897297d", "role": "qa-engineer", "kind": "role", "difficulty": "hard", "category": "Process", "question": "A bug reached production. How do you stop that class of bug reaching it again?", "key_points": ["Finds the root cause, not only the fix", "Adds a test that would have caught it", "Checks whether similar code has the same problem", "Improves the process: review checklist, monitoring, release steps"], "source_url": null, "sort_order": 9},
{"id": "470a15be-06d5-579c-b78e-147e545d7d1b", "role": "qa-engineer", "kind": "role", "difficulty": "easy", "category": "Test design", "question": "What is the difference between smoke testing and regression testing?", "key_points": ["Smoke: a quick check that the main features work after a new build", "Regression: checks that old features still work after a change", "Smoke first; a full regression run before release"], "source_url": null, "sort_order": 10},
{"id": "9f802c8b-f024-5011-9c39-d9d3d34a6125", "role": "qa-engineer", "kind": "role", "difficulty": "easy", "category": "Test design", "question": "What are boundary values? Give an example for an amount field that accepts 100 to 5,000 taka.", "key_points": ["Test just below, at, and just above each limit", "Here: 99, 100 and 101, then 4,999, 5,000 and 5,001", "Bugs often hide at the edges"], "source_url": null, "sort_order": 11},
{"id": "7d0823c4-e6b5-5eaa-97ee-570287f0a4ea", "role": "qa-engineer", "kind": "role", "difficulty": "medium", "category": "Mobile testing", "question": "How would you test a form that must accept both Bangla and English input?", "key_points": ["Types with real Bangla keyboards, including joined letters and Bangla digits", "Checks saving, searching and display after reload", "Tests mixed text, long text, and copy and paste", "Checks validation, such as a phone number typed in Bangla digits"], "source_url": null, "sort_order": 12},
{"id": "2df0b6fc-ef15-56ad-b0a2-714f76edf992", "role": "qa-engineer", "kind": "role", "difficulty": "medium", "category": "Mobile testing", "question": "How do you test an app on a weak or changing mobile network?", "key_points": ["Uses network throttling, or a real weak signal", "Switches between Wi-Fi and mobile data, and goes offline mid-action", "Checks timeouts, retries and clear error messages", "Makes sure no action is lost or done twice"], "source_url": null, "sort_order": 13},
{"id": "5e807402-a506-585f-bea9-2912c697ffa7", "role": "qa-engineer", "kind": "role", "difficulty": "hard", "category": "Release risk", "question": "The team wants to release today, but you found a bug that affects a small group of users. What do you do?", "key_points": ["Describes the impact clearly: who, how often, how bad", "Gives options: fix now, release with a known issue, or hide the feature", "Lets the product owner decide with the facts", "Records the decision and plans the fix"], "source_url": null, "sort_order": 14},
{"id": "404f8546-e609-5dca-8bc3-7c30167bac3a", "role": "qa-engineer", "kind": "role", "difficulty": "hard", "category": "Mobile testing", "question": "Your users have hundreds of different low-cost Android phones. How do you choose which devices to test on?", "key_points": ["Uses analytics to find the most common models, OS versions and screen sizes", "Covers low RAM, small screens and old Android versions", "Mixes real devices with a cloud device lab or emulators", "Reviews the list every few months"], "source_url": null, "sort_order": 15},
{"id": "0548bb32-6cc4-563a-a71c-e7423b1447c2", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "easy", "category": "GMP", "question": "What is GMP, and why does it matter in a pharmaceutical plant?", "key_points": ["Good manufacturing practice: making medicines safely and the same way every time", "Covers people, premises, equipment, materials and records", "Quality is built into every step, not only tested at the end", "In Bangladesh, DGDA licenses drug factories and inspects them"], "source_url": "https://dgda.gov.bd/", "sort_order": 1},
{"id": "d5dbf870-3f4a-5def-93c3-e43f01d512eb", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "easy", "category": "QC tests", "question": "What is the difference between QA and QC?", "key_points": ["QC tests materials and products against their specifications", "QA builds the system: SOPs, training, audits and batch release", "QC is one part of QA", "Both are needed before a batch is released"], "source_url": null, "sort_order": 2},
{"id": "5eb82b2c-b09c-5d39-b53f-dd7e473f1e5e", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "easy", "category": "Lab safety", "question": "What safety steps do you follow when handling acids and solvents in a lab?", "key_points": ["Wear the right PPE: lab coat, gloves and goggles", "Use a fume hood and read the safety data sheet", "Label, store and dispose of chemicals correctly", "Know where the eyewash, shower and spill kit are"], "source_url": null, "sort_order": 3},
{"id": "bd9b4abe-7cb5-5c8f-9edb-ea66f8d19b5d", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "easy", "category": "Validation", "question": "What is calibration, and why must lab instruments be calibrated?", "key_points": ["Checking an instrument's readings against a known standard", "Wrong readings lead to wrong results and wrong decisions", "Follow the calibration schedule and record each one", "Never use an instrument that is out of calibration"], "source_url": null, "sort_order": 4},
{"id": "e8d37b39-5dfb-5354-b328-2399a9826b92", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "easy", "category": "SOPs", "question": "Why must you follow an SOP exactly, even when you know a faster way?", "key_points": ["The SOP is the approved, validated way to do the task", "Unapproved changes can affect results and break GMP", "Suggest improvements through change control", "Records must match what was really done"], "source_url": null, "sort_order": 5},
{"id": "bff31af9-e77e-5dbe-9fd8-dfbab4d7855f", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "medium", "category": "QC tests", "question": "Walk me through how you would run an HPLC assay for a tablet.", "key_points": ["Prepare mobile phase, standard and sample solutions as the method says", "Check system suitability before running samples", "Run the samples, integrate the peaks and calculate the result", "Record everything and compare with the specification"], "source_url": null, "sort_order": 6},
{"id": "e18838d3-7c75-5629-a387-5b904b9cfc3a", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "medium", "category": "Deviations and CAPA", "question": "What is an out-of-specification result, and what do you do when you get one?", "key_points": ["A result outside the approved specification", "Never retest or discard it outside the OOS procedure", "Report it and start a lab investigation for errors", "If no lab error is found, the investigation moves to production"], "source_url": null, "sort_order": 7},
{"id": "0a54961c-6e4c-55c1-b48c-2f716ca692b2", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "medium", "category": "Data integrity", "question": "What does ALCOA+ mean for lab records?", "key_points": ["Attributable, legible, contemporaneous, original and accurate", "Plus complete, consistent, enduring and available", "Record at the time of the work, in ink or a secure system", "Never back-date or overwrite raw data"], "source_url": null, "sort_order": 8},
{"id": "d67b59b2-b9da-5507-88cb-68a25ae9bee0", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "medium", "category": "Stability", "question": "What is a stability study, and why is it done?", "key_points": ["Tests a product over time at set temperature and humidity", "Shows how long it stays within specification", "Supports the expiry date and the storage instructions", "ICH and WHO guidance set the conditions, including for hot, humid climates"], "source_url": "https://www.ich.org/", "sort_order": 9},
{"id": "03f8cea3-492f-5783-9380-c751a6a0e3c1", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "medium", "category": "QC tests", "question": "How would you take a representative sample from a large lot of raw material?", "key_points": ["Follow the sampling SOP: how many containers and from where", "Use clean tools in a clean area to avoid contamination", "Label samples clearly and keep the records linked", "Mark sampled containers and reseal them properly"], "source_url": null, "sort_order": 10},
{"id": "2c9cbbf3-2c62-54e9-ad57-1d8d6aa83adc", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "hard", "category": "Deviations and CAPA", "question": "A batch failed dissolution testing. How would you investigate, and what is CAPA?", "key_points": ["Check the lab first: method, equipment, analyst and samples", "Then check batch records, materials and any process changes", "Find the root cause with a tool such as five whys or a fishbone", "CAPA: correct this case, and prevent it happening again"], "source_url": null, "sort_order": 11},
{"id": "98bd2e9c-3864-5e1d-a874-222f5e911b0e", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "hard", "category": "Data integrity", "question": "You see a colleague delete a chromatogram and run the sample again without recording why. What do you do?", "key_points": ["This is a serious data integrity problem", "Do not ignore it: report it to your supervisor or QA", "Audit trails will show it, so hiding it makes it worse", "Support a fair investigation and retraining"], "source_url": null, "sort_order": 12},
{"id": "46eb1513-f0f6-5466-94ea-e5b1a00711d2", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "hard", "category": "GMP", "question": "Your plant is preparing for an inspection by a foreign regulator before export. What do you check in the QC lab?", "key_points": ["SOPs are current and followed, and training records are complete", "Instruments are calibrated and qualified, with logs filled in", "Raw data, audit trails and OOS investigations are in order", "Staff can answer questions honestly and simply"], "source_url": null, "sort_order": 13},
{"id": "871dfa39-bd6b-5514-9d81-1039b41252ff", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "hard", "category": "Stability", "question": "Power fails overnight during load shedding while a stability chamber is running. What do you do?", "key_points": ["Check the backup power log and the chamber's temperature record", "Judge the effect on the samples and record a deviation", "Repeat the study or justify the data, with QA approval", "Fix the backup power problem so it does not happen again"], "source_url": null, "sort_order": 14},
{"id": "8ffeb513-bc4b-5894-90f4-6ce64bf38e31", "role": "pharmaceutical-quality-analyst", "kind": "role", "difficulty": "hard", "category": "Validation", "question": "A test method is being transferred to your lab from another site. How would you prove it works in your lab?", "key_points": ["Agree a protocol with acceptance criteria before starting", "Test accuracy, precision, specificity, linearity and range as needed", "Compare your results with the sending lab's results", "Write a report and get QA approval before routine use"], "source_url": null, "sort_order": 15},
{"id": "b53ea760-6d90-54db-9053-201e0fcfe396", "role": "medical-promotion-officer", "kind": "role", "difficulty": "easy", "category": "Pharmacology basics", "question": "What is the difference between the generic name and the brand name of a medicine?", "key_points": ["Generic name: the active ingredient, the same everywhere", "Brand name: a company's own name for its product", "Many brands can share one generic", "Doctors often prescribe by brand, so brand recall matters"], "source_url": null, "sort_order": 1},
{"id": "feb8d399-ba70-5055-bf28-54a29c9186e4", "role": "medical-promotion-officer", "kind": "role", "difficulty": "easy", "category": "Pharmacology basics", "question": "What is the difference between an antibiotic and a painkiller? Give an example of each.", "key_points": ["Antibiotics kill or stop bacteria and do not work on viruses", "Painkillers ease pain, and some also lower fever", "Examples: amoxicillin and paracetamol", "Misusing antibiotics leads to resistance"], "source_url": null, "sort_order": 2},
{"id": "a60c1a06-5e4f-5f3c-b895-0c53b1edaa15", "role": "medical-promotion-officer", "kind": "role", "difficulty": "easy", "category": "Product detailing", "question": "What is detailing, and what happens in a typical doctor visit?", "key_points": ["Presenting a product's key benefits and evidence to a doctor", "A short visit: greet, give the key message, answer questions, ask for support", "Leave approved literature or samples where allowed", "Record the visit and follow up"], "source_url": null, "sort_order": 3},
{"id": "44b00b34-4723-5d3e-882f-e36a6b5b299f", "role": "medical-promotion-officer", "kind": "role", "difficulty": "easy", "category": "Territory planning", "question": "How would you plan your day to cover doctors' chambers and pharmacies in your area?", "key_points": ["Group calls by location to save travel", "Visit doctors during their chamber hours, often in the evening", "Fit pharmacy visits between doctor calls", "Record calls and plan the next day"], "source_url": null, "sort_order": 4},
{"id": "eb91bb96-4b25-516c-a3c8-427f4f70877c", "role": "medical-promotion-officer", "kind": "role", "difficulty": "easy", "category": "Chemist coverage", "question": "Why are pharmacies important for a medical promotion officer?", "key_points": ["They show which products are prescribed and sold", "Stock in pharmacies stops prescriptions going to other brands", "Good relations with pharmacy owners help", "Report stock-outs and competitor activity"], "source_url": null, "sort_order": 5},
{"id": "a2392cc6-aafd-5688-82a7-134aa7bf9fdd", "role": "medical-promotion-officer", "kind": "role", "difficulty": "medium", "category": "Product detailing", "question": "A busy doctor gives you one minute. What do you say?", "key_points": ["One clear message: which patients the product is for, and why", "One proof point from approved material", "A simple request, such as trying it for suitable patients", "Thank them and leave on time"], "source_url": null, "sort_order": 6},
{"id": "25d77332-7f38-5bec-a959-a8018acf7c07", "role": "medical-promotion-officer", "kind": "role", "difficulty": "medium", "category": "Communication", "question": "A doctor asks about a side effect you cannot answer. What do you do?", "key_points": ["Be honest and say you will find out", "Never guess or give wrong information", "Get the answer from the medical department", "Follow up quickly with approved information"], "source_url": null, "sort_order": 7},
{"id": "9e7b4f0b-69e9-5231-b741-59baf3ec2ffa", "role": "medical-promotion-officer", "kind": "role", "difficulty": "medium", "category": "Targets", "question": "You are behind your monthly target. What do you do?", "key_points": ["Find where the gap is: which doctors, products and pharmacies", "Focus on high-potential doctors and check stock in nearby pharmacies", "Improve the quality of calls, not only the number", "Tell your manager early, with a plan"], "source_url": null, "sort_order": 8},
{"id": "133f4465-d7a2-59fd-be66-75e3cda14e08", "role": "medical-promotion-officer", "kind": "role", "difficulty": "medium", "category": "Chemist coverage", "question": "Doctors are prescribing your product, but pharmacies say they have no stock. What do you do?", "key_points": ["Check supply with the depot and distributor", "Tell your manager and the supply team quickly", "Visit key pharmacies to arrange stock", "Tell doctors when stock is back so they keep trusting you"], "source_url": null, "sort_order": 9},
{"id": "07ba157a-c90e-5e5b-a108-07cefd772f2c", "role": "medical-promotion-officer", "kind": "role", "difficulty": "medium", "category": "Territory planning", "question": "Your territory has towns and remote upazilas. How do you plan coverage for the month?", "key_points": ["List doctors by importance and potential", "Set how often to visit each one", "Visit remote areas on fixed days with sensible routes", "Review coverage every week"], "source_url": null, "sort_order": 10},
{"id": "ef5a0f6e-5a21-5948-ac44-e110d6e3f286", "role": "medical-promotion-officer", "kind": "role", "difficulty": "hard", "category": "Ethics", "question": "A doctor hints they will prescribe your product if you give an expensive gift. What do you do?", "key_points": ["Politely refuse: gifts in return for prescriptions are unethical", "Offer only approved information and support", "Report it as company policy requires", "Keep the focus on the product's real benefits"], "source_url": null, "sort_order": 11},
{"id": "4287356f-7c94-5255-89fd-f8c773ab9930", "role": "medical-promotion-officer", "kind": "role", "difficulty": "hard", "category": "Ethics", "question": "Your manager tells you to say your product is better than a competitor's, but there is no evidence. What do you do?", "key_points": ["Only make claims backed by approved product information and evidence", "Ask the medical department for approved comparison data", "Refuse to make false claims, even under pressure", "False claims harm patients, doctors' trust and the company"], "source_url": null, "sort_order": 12},
{"id": "623cc57a-36d6-5776-ae83-801f76168538", "role": "medical-promotion-officer", "kind": "role", "difficulty": "hard", "category": "Product detailing", "question": "A doctor says your brand costs more than others with the same generic. How do you respond?", "key_points": ["Accept the price difference honestly", "Explain quality points you can prove, such as consistent manufacturing", "Respect the doctor's choice for patients who cannot afford it", "Never criticise a competitor unfairly"], "source_url": null, "sort_order": 13},
{"id": "0c913206-f2b1-596b-b0f7-9226ed441c96", "role": "medical-promotion-officer", "kind": "role", "difficulty": "hard", "category": "Targets", "question": "A new competitor is visiting all your key doctors and your prescriptions are falling. What is your plan?", "key_points": ["Find out what they are offering and saying", "Strengthen relationships with regular, useful visits", "Use approved scientific material and medical education events", "Track prescriptions doctor by doctor"], "source_url": null, "sort_order": 14},
{"id": "8017f53d-4e09-5b72-8a06-217c47d8f48d", "role": "medical-promotion-officer", "kind": "role", "difficulty": "hard", "category": "Communication", "question": "How would you present a new product to a small group of doctors at a meeting?", "key_points": ["Prepare a short talk with approved slides", "Start with the patient problem, then the evidence", "Leave time for questions and answer honestly", "Follow up with the doctors who show interest"], "source_url": null, "sort_order": 15},
{"id": "14b3a2d3-db10-595b-92ab-86c83d1069c2", "role": "management-trainee", "kind": "role", "difficulty": "easy", "category": "Business awareness", "question": "Pick a business you know well. How does it make money, and what are its biggest costs?", "key_points": ["Names the customer and what they pay for", "Main costs, such as materials, staff, rent and delivery", "One clear way it could earn more or spend less"], "source_url": null, "sort_order": 1},
{"id": "05ffea80-fd2e-5b1f-987c-83e01b8e6338", "role": "management-trainee", "kind": "role", "difficulty": "easy", "category": "Motivation", "question": "Why do you want to join a management trainee programme rather than a job in one department?", "key_points": ["Wants to learn how departments work together", "Ready for rotation and postings outside Dhaka", "Links the choice to a real experience, such as a club or internship", "Shows a long-term plan with the company"], "source_url": null, "sort_order": 2},
{"id": "2837ed63-6931-5128-bf5d-76235d260de0", "role": "management-trainee", "kind": "role", "difficulty": "easy", "category": "Numbers", "question": "A shop buys a product for 80 taka and sells it for 100 taka. What is the profit margin, and what is the mark-up?", "key_points": ["Profit is 20 taka on each piece", "Margin is profit over the selling price: one fifth", "Mark-up is profit over the cost: one quarter", "Explains why the two numbers are different"], "source_url": null, "sort_order": 3},
{"id": "ac4a22e6-f90e-519e-875b-d3b8cbd548e8", "role": "management-trainee", "kind": "role", "difficulty": "easy", "category": "Leadership", "question": "You lead a group project and one member is not doing their part. What do you do?", "key_points": ["Talks to them early and in private to find the reason", "Shares the work again with clear tasks and dates", "Tells the teacher or supervisor only when needed, with facts", "Keeps the rest of the group informed and treats everyone fairly"], "source_url": null, "sort_order": 4},
{"id": "daeea8c6-76fb-558d-8c4d-f1f3cb18817a", "role": "management-trainee", "kind": "role", "difficulty": "easy", "category": "Problem solving", "question": "You are posted to a regional depot outside Dhaka in your first month. How do you learn the work quickly?", "key_points": ["Reads the SOPs and works beside experienced staff", "Walks the floor: stock, trucks, shops and paperwork", "Keeps a daily note of questions and answers", "Earns the local team's trust before suggesting changes"], "source_url": null, "sort_order": 5},
{"id": "a8006a7a-a1b1-5df7-bcf2-3d62f04e7d8d", "role": "management-trainee", "kind": "role", "difficulty": "medium", "category": "Estimation", "question": "How many cups of tea are sold in Dhaka in one day? Walk us through your estimate.", "key_points": ["States each assumption out loud, such as people who drink tea outside", "Splits the problem, for example tea stalls times cups per stall", "Uses round numbers and shows the maths", "Checks the answer a second way to see if it is sensible"], "source_url": null, "sort_order": 6},
{"id": "43f287e3-6b15-5f08-9570-71b565b7a41a", "role": "management-trainee", "kind": "role", "difficulty": "medium", "category": "Numbers", "question": "Sales went up this year but profit went down. What could explain this?", "key_points": ["Costs grew faster than sales: materials, freight, wages or the exchange rate", "More discounts, or more sales of cheaper products", "Higher spending on marketing, or customers who did not pay", "Checks it by comparing each cost line with last year"], "source_url": null, "sort_order": 7},
{"id": "c44c329c-b7c2-5a69-9ffe-7bf2e61116d0", "role": "management-trainee", "kind": "role", "difficulty": "medium", "category": "Leadership", "question": "In a group discussion, two people keep talking and one person has said nothing. What do you do?", "key_points": ["Invites the quiet person in with a direct, polite question", "Sums up the points so far to move the group forward", "Keeps time and steers the group to a conclusion", "Leads without taking over: assessors watch listening too"], "source_url": null, "sort_order": 8},
{"id": "837af5d3-0c0b-534d-8056-4b1e6380cd09", "role": "management-trainee", "kind": "role", "difficulty": "medium", "category": "Business awareness", "question": "A competitor launches the same product at a lower price. What would you suggest we do?", "key_points": ["First finds out why it is cheaper: smaller pack, lower quality or lower margin", "Checks our customers, sales and margins before reacting", "Options: add value, launch a smaller pack or make a targeted offer", "Avoids a price war that hurts everyone"], "source_url": null, "sort_order": 9},
{"id": "35c4a4b0-cf88-5472-b59d-10b694440482", "role": "management-trainee", "kind": "role", "difficulty": "medium", "category": "Communication", "question": "You have five minutes to present a recommendation to senior managers. How do you structure it?", "key_points": ["Starts with the answer, then the reasons", "Two or three facts that support it, with numbers", "Names the risks and what is needed from the managers", "Finishes on time and leaves room for questions"], "source_url": null, "sort_order": 10},
{"id": "392735b9-84d2-581b-8c62-8ff5326322a2", "role": "management-trainee", "kind": "role", "difficulty": "hard", "category": "Estimation", "question": "Estimate the monthly market for mobile recharge in a district town. What would you need to check?", "key_points": ["Builds it from people, phone users and average spend each month", "Splits users into groups, such as students, workers and shop owners", "Tests the assumptions by asking a few recharge shops", "Says which assumption matters most and how to check it"], "source_url": null, "sort_order": 11},
{"id": "91b3a1c7-7062-5772-857a-3330c42a5134", "role": "management-trainee", "kind": "role", "difficulty": "hard", "category": "Problem solving", "question": "Deliveries from a depot have been late for three weeks running. You are asked to find out why. What do you do?", "key_points": ["Maps each step: order, loading, dispatch, route and delivery", "Uses data to see which routes, days or trucks are late", "Talks to drivers and depot staff, not only managers", "Fixes the biggest cause first and measures again"], "source_url": null, "sort_order": 12},
{"id": "44f1a8be-dee2-53d8-adf1-0388de8d4260", "role": "management-trainee", "kind": "role", "difficulty": "hard", "category": "Leadership", "question": "You lead a team of staff who have worked here for many years, and they do not take you seriously. What do you do?", "key_points": ["Listens first and learns from their experience", "Earns trust with small wins and by sharing the hard work", "Is clear about targets and fair to everyone", "Asks the manager for support only when it is really needed"], "source_url": null, "sort_order": 13},
{"id": "03ea94ee-034b-5cfb-aebe-4dbd629a4bd8", "role": "management-trainee", "kind": "role", "difficulty": "hard", "category": "Business awareness", "question": "The taka has weakened and our main imported raw material now costs much more. What are our options?", "key_points": ["Explains why a weaker taka makes imports cost more", "Options: local suppliers, bigger orders, a price change or a smaller pack", "Works with finance on when to open LCs and make payments", "Weighs each option against customers and competitors"], "source_url": null, "sort_order": 14},
{"id": "f6dc336a-8217-54b6-aff6-1e9d631edbae", "role": "management-trainee", "kind": "role", "difficulty": "hard", "category": "Ethics", "question": "During your rotation you notice a supervisor is recording more stock than is really there. What do you do?", "key_points": ["Checks the facts quietly: counts, records and documents", "Does not accuse anyone in public and does not cover it up", "Reports it to the line manager or the right channel, in writing", "Keeps notes of what was found and when"], "source_url": null, "sort_order": 15},
{"id": "8d8803ae-2303-5f3b-a2ac-f674c443de7e", "role": "business-analyst", "kind": "role", "difficulty": "easy", "category": "Role", "question": "What does a business analyst actually do day to day?", "key_points": ["Learns the problem and the needs from users and managers", "Writes requirements and maps processes", "Works between business teams and developers", "Checks the solution meets the need, including testing"], "source_url": null, "sort_order": 1},
{"id": "1c2dbdfd-93a2-5bbc-9da2-c30d2b7369d9", "role": "business-analyst", "kind": "role", "difficulty": "easy", "category": "Requirements", "question": "What is a requirement, and what makes a bad one?", "key_points": ["A clear statement of what a system or process must do", "Good: specific, testable and agreed by the owner", "Bad: vague words like 'fast' or 'easy', or a solution dressed up as a need", "Bad: two needs in one, or nobody owns it"], "source_url": null, "sort_order": 2},
{"id": "7c1df36c-6d14-5462-b56d-5ea14f28ed5e", "role": "business-analyst", "kind": "role", "difficulty": "easy", "category": "Communication", "question": "How would you explain a process to somebody who has never seen it?", "key_points": ["Start with the purpose and who is involved", "Walk through the steps in order with a simple diagram", "Follow one real example from start to finish", "Check understanding by asking them to explain it back"], "source_url": null, "sort_order": 3},
{"id": "86196ba3-ddc4-501d-b437-a653af961689", "role": "business-analyst", "kind": "role", "difficulty": "medium", "category": "Requirements", "question": "A stakeholder asks for a feature. How do you find out what they actually need?", "key_points": ["Ask what problem they want to solve and why now", "Watch how they work today, not only what they say", "Ask for examples and how they will know it worked", "Confirm in writing and check with other users"], "source_url": null, "sort_order": 4},
{"id": "6eb4dea8-76c3-5448-a1dc-05a541ad1931", "role": "business-analyst", "kind": "role", "difficulty": "medium", "category": "Process mapping", "question": "Map the process of a customer returning a product.", "key_points": ["Start and end: return request to refund or exchange", "Steps and owners: customer, support, courier, warehouse, finance", "Decision points: within policy, item condition, refund method", "Spot the delays and hand-offs where it goes wrong"], "source_url": null, "sort_order": 5},
{"id": "bf1d87d8-787a-55a8-8667-6eb203da89a7", "role": "business-analyst", "kind": "role", "difficulty": "medium", "category": "Stakeholders", "question": "Two departments disagree about how a process should work. What do you do?", "key_points": ["Meet each side to understand their goals and limits", "Bring facts: the process map, data, costs and risks of each option", "Look for an option that meets the shared goal", "If there is no agreement, take clear options to the decision maker"], "source_url": null, "sort_order": 6},
{"id": "d2168d63-c25e-5980-a29c-6f5da8acb550", "role": "business-analyst", "kind": "role", "difficulty": "hard", "category": "Prioritising", "question": "How do you decide whether a change is worth making at all?", "key_points": ["Estimate the value: time saved, money, risk reduced, customers helped", "Estimate the cost and effort, including training", "Compare it with other work, for example value against effort", "Say no, or not now, with reasons"], "source_url": null, "sort_order": 7},
{"id": "793531d9-7f02-55b0-b047-d67c4360db32", "role": "business-analyst", "kind": "role", "difficulty": "hard", "category": "Prioritising", "question": "A project is late and the scope keeps growing. How do you handle it?", "key_points": ["Put every new request through change control with its effect on time and cost", "Agree with the sponsor what must be in the first release", "Re-plan honestly and share the new date", "Move nice-to-have items to a later phase"], "source_url": null, "sort_order": 8},
{"id": "1323e6e3-f5f1-5b90-a94a-21e833da43cf", "role": "business-analyst", "kind": "role", "difficulty": "hard", "category": "Data", "question": "How would you prove a process change actually improved something?", "key_points": ["Measure a baseline before the change", "Pick a few clear measures: time, errors, cost, satisfaction", "Compare after the change over enough time, and rule out other causes", "Share the result, good or bad"], "source_url": null, "sort_order": 9},
{"id": "85e2d24b-2c97-5766-8f61-aa23854ac51d", "role": "business-analyst", "kind": "role", "difficulty": "easy", "category": "Requirements", "question": "What is a user story, and what makes a good one?", "key_points": ["A short need written from the user's view: as a, I want, so that", "Small enough to build in one sprint", "Has clear acceptance criteria", "Agreed with users and the team"], "source_url": null, "sort_order": 10},
{"id": "abba7398-f838-525b-98b8-52eb84cea8a6", "role": "business-analyst", "kind": "role", "difficulty": "easy", "category": "Testing", "question": "What is user acceptance testing, and who should do it?", "key_points": ["Real users confirm the system meets their needs", "Done after the team's own testing, before go-live", "Uses real scenarios built from the requirements", "Ends with the business owner's sign-off and logged issues"], "source_url": null, "sort_order": 11},
{"id": "049de8d8-caa9-5ddc-aa03-b43e41277b25", "role": "business-analyst", "kind": "role", "difficulty": "medium", "category": "Process mapping", "question": "A loan approval process runs on paper files that move from desk to desk. How would you move it to a digital system?", "key_points": ["Map the current steps and time each one, including waiting", "Ask why each signature or copy exists before copying it into the system", "Remove or combine steps where the rules allow", "Plan training and a period when both ways run together"], "source_url": null, "sort_order": 12},
{"id": "036d5ffe-6db1-5371-bf3d-2d1499d78088", "role": "business-analyst", "kind": "role", "difficulty": "medium", "category": "Stakeholders", "question": "Front-line staff who mostly read Bangla and are new to apps will use the new system. What changes in your requirements?", "key_points": ["Bangla labels and simple words, tested with real staff", "Few steps per task, and it works on low-end phones and slow data", "Training, short videos and someone to call for help", "Watch them use it and fix what confuses them"], "source_url": null, "sort_order": 13},
{"id": "ab30a9d4-0c22-5ee6-baac-f9fc324cfbaf", "role": "business-analyst", "kind": "role", "difficulty": "hard", "category": "Data", "question": "Management wants a dashboard but cannot say what decisions it will support. How do you handle it?", "key_points": ["Ask what decisions they make each week and what they need to know", "Start with a few key measures, each clearly defined", "Check where the data comes from and how reliable it is", "Build a simple version, get feedback and improve it"], "source_url": null, "sort_order": 14},
{"id": "8210a5d6-4708-596c-a13a-29635d5e7fed", "role": "business-analyst", "kind": "role", "difficulty": "hard", "category": "Testing", "question": "The system goes live next week, but users found serious bugs in testing. What do you recommend?", "key_points": ["List the bugs by business impact and risk", "Agree with the sponsor what must be fixed before go-live", "Options: delay, go live with a workaround, or release in phases", "Put the risk in writing so the decision is informed"], "source_url": null, "sort_order": 15},
{"id": "aa5941a7-7b12-5db8-9014-0ecca5bd549e", "role": "hr-executive", "kind": "role", "difficulty": "easy", "category": "Recruitment", "question": "What would you look at first on a CV, and why?", "key_points": ["The must-have requirements of the role", "Evidence of results, not only duties", "Gaps or frequent moves to ask about, without assuming the worst", "Clear, honest writing and correct contact details"], "source_url": null, "sort_order": 1},
{"id": "0c5020ce-eb87-5aa2-a7e9-aae67da3647b", "role": "hr-executive", "kind": "role", "difficulty": "easy", "category": "Recruitment", "question": "What is the difference between recruitment and selection?", "key_points": ["Recruitment attracts a pool of suitable candidates", "Selection chooses the best person from that pool", "Recruitment uses adverts, job sites, referrals and campus visits", "Selection uses screening, tests, interviews and reference checks"], "source_url": null, "sort_order": 2},
{"id": "e9962417-7955-53d6-834e-34feeb0f0dca", "role": "hr-executive", "kind": "role", "difficulty": "easy", "category": "Recruitment", "question": "How would you write a job advert for a junior developer?", "key_points": ["Clear title, location and what the person will do", "Short lists of must-have and nice-to-have skills", "Pay range or benefits where allowed, and how to apply", "Fair wording with no demands unrelated to the job"], "source_url": null, "sort_order": 3},
{"id": "2f2c5991-68e9-5633-8e8d-f1a25b8075c6", "role": "hr-executive", "kind": "role", "difficulty": "medium", "category": "Employee relations", "question": "Two managers want the same candidate. How do you handle it?", "key_points": ["Ask the candidate what they want and which role fits their skills", "Look at business priority and timing for each role", "Bring the managers together with the facts to agree", "Keep other candidates in the pipeline"], "source_url": null, "sort_order": 4},
{"id": "12292dad-19bc-566f-9dcc-487c3713cb5f", "role": "hr-executive", "kind": "role", "difficulty": "medium", "category": "Labour law", "question": "What does the Bangladesh Labour Act say about notice periods?", "key_points": ["Notice depends on who ends the job and the worker's type, such as permanent or temporary", "The Act also allows pay in place of notice", "Check the current Act and its amendments on the official laws website before quoting days", "An appointment letter or service rules cannot give a worker less than the Act"], "source_url": "https://bdlaws.minlaw.gov.bd/act-952.html", "sort_order": 5},
{"id": "172b1e44-66cf-5206-aaf8-0ecbc4d2fcdc", "role": "hr-executive", "kind": "role", "difficulty": "medium", "category": "Employee relations", "question": "An employee complains about their manager. What do you do first?", "key_points": ["Listen in private, take notes and thank them for raising it", "Check if it is a safety, harassment or legal matter that needs urgent action", "Explain the process and keep it confidential as far as possible", "Investigate fairly, hear both sides and prevent any revenge"], "source_url": null, "sort_order": 6},
{"id": "83f2be80-464a-5ee2-bbd3-fb16bb33cd41", "role": "hr-executive", "kind": "role", "difficulty": "hard", "category": "Onboarding", "question": "Half your new hires leave within six months. How do you find out why?", "key_points": ["Look at the data: which teams, managers and roles, and when people leave", "Hold exit interviews and talk to people who stayed", "Check if the job matched the advert and the offer", "Fix the biggest cause, such as onboarding or one manager, and track again"], "source_url": null, "sort_order": 7},
{"id": "138b970c-7e64-57cc-a0ed-c77bb0a214e9", "role": "hr-executive", "kind": "role", "difficulty": "hard", "category": "Recruitment", "question": "Design a fair interview process for a role with three hundred applicants.", "key_points": ["Screen against clear must-have criteria with a scoring sheet", "Use a short test or phone screen to make a shortlist", "Structured interviews with the same questions and a panel", "Record decisions and keep candidates informed"], "source_url": null, "sort_order": 8},
{"id": "0f695fbf-7efc-55b4-8b08-35f3626989f7", "role": "hr-executive", "kind": "role", "difficulty": "hard", "category": "Performance", "question": "An employee is underperforming. Take me through the conversation and what you write down.", "key_points": ["Prepare facts and examples, and meet in private", "Listen for causes: skills, workload, health or personal problems", "Agree clear targets, support and a review date, in writing", "Follow the company process if it leads to warnings"], "source_url": null, "sort_order": 9},
{"id": "21cd8862-22c1-5abe-9afa-cb275636cb7d", "role": "hr-executive", "kind": "role", "difficulty": "easy", "category": "Onboarding", "question": "What should a new employee's first week look like?", "key_points": ["Ready on day one: ID card, email, equipment and papers", "Meets the team and learns the key policies and safety rules", "Has a buddy and a check-in with the manager", "Clear first tasks and goals for the first months"], "source_url": null, "sort_order": 10},
{"id": "a5da0c4a-96cc-5893-9f53-32ab72738425", "role": "hr-executive", "kind": "role", "difficulty": "easy", "category": "Payroll and attendance", "question": "What information do you need to run monthly payroll correctly?", "key_points": ["Attendance, leave and overtime records", "Pay structure, allowances and deductions such as tax and provident fund", "New joiners, leavers and approved changes, received on time", "A check against last month before payment"], "source_url": null, "sort_order": 11},
{"id": "d6f0a09b-c74f-530f-a363-fcb7e11e37a1", "role": "hr-executive", "kind": "role", "difficulty": "medium", "category": "Labour law", "question": "How would you explain festival bonus, provident fund and gratuity to a new employee, and where would you check the rules?", "key_points": ["Festival bonus: paid before major festivals under the labour rules and company policy", "Provident fund: the employee and employer both save each month for later", "Gratuity: a payment for long service when someone leaves", "Check the Labour Act, its rules and the company policy for who qualifies"], "source_url": "https://mole.gov.bd/", "sort_order": 12},
{"id": "35873c6d-9594-57b8-a608-5fbf8febe1bc", "role": "hr-executive", "kind": "role", "difficulty": "medium", "category": "Employee relations", "question": "A team member says a colleague keeps making unwelcome comments that make her uncomfortable. What do you do?", "key_points": ["Take it seriously, listen and write down what she says", "Keep it confidential and protect her from revenge", "Follow the company's harassment policy and complaint process", "Investigate fairly and act on what is found"], "source_url": null, "sort_order": 13},
{"id": "aa7d78d2-1587-541c-862e-5c62b7e5a278", "role": "hr-executive", "kind": "role", "difficulty": "hard", "category": "Labour law", "question": "A factory needs to set up its participation committee. What is HR's role, and where do you check the rules?", "key_points": ["Participation committees come from the Labour Act and its rules; check the current amended text", "Run a fair, open process for workers to choose their representatives", "Help set up regular meetings and keep minutes", "Treat it as a way to solve problems early"], "source_url": "https://bdlaws.minlaw.gov.bd/act-952.html", "sort_order": 14},
{"id": "ae2b62d2-75dc-5776-962a-ae5c08573d04", "role": "hr-executive", "kind": "role", "difficulty": "hard", "category": "Policy", "question": "Management wants to cut costs by not paying overtime properly. How do you respond?", "key_points": ["Explain that overtime pay is a duty under the Labour Act, and the audit risk", "Suggest lawful ways to cut overtime: better planning, shifts, more hiring", "Put the advice in writing", "Escalate if asked to break the law"], "source_url": "https://bdlaws.minlaw.gov.bd/act-952.html", "sort_order": 15},
{"id": "adaf7f3b-cb8e-5650-a49a-4a0935bf6c9f", "role": "operations-executive", "kind": "role", "difficulty": "easy", "category": "Process", "question": "What is an SOP, and why does an operations team need one?", "key_points": ["A standard operating procedure: written steps for a routine task", "Everyone does the task the same, safe way", "Helps train new staff and cover absences", "Reviewed when the work or the rules change"], "source_url": null, "sort_order": 1},
{"id": "10f1f805-e1ac-58e6-be58-e590bd5060af", "role": "operations-executive", "kind": "role", "difficulty": "easy", "category": "Scheduling", "question": "How would you make a weekly shift roster for a team of twelve?", "key_points": ["Start from the work needed each day and hour", "Balance skills across shifts", "Be fair with nights, weekends and holidays", "Share it early and plan for absences"], "source_url": null, "sort_order": 2},
{"id": "8129ac7b-d509-5be2-81eb-72b67e0ded2e", "role": "operations-executive", "kind": "role", "difficulty": "easy", "category": "Reporting", "question": "What would you put in a daily operations report for your manager?", "key_points": ["Key numbers against target: volume, time, quality", "Today's problems and what was done", "Risks for tomorrow and help needed", "Short, in the same format every day"], "source_url": null, "sort_order": 3},
{"id": "85086886-0c09-5ade-a76b-7b3387879aa5", "role": "operations-executive", "kind": "role", "difficulty": "easy", "category": "Service quality", "question": "A customer is very upset and complains to you in person. How do you handle it?", "key_points": ["Listen fully without interrupting and stay calm", "Say sorry for their experience and show you understand", "Fix what you can now and say clearly what happens next", "Record it and follow up"], "source_url": null, "sort_order": 4},
{"id": "8977aa94-8b7d-54ad-a0ca-57c140fe090f", "role": "operations-executive", "kind": "role", "difficulty": "easy", "category": "Inventory", "question": "How do you keep track of supplies so a team never runs out of something it needs?", "key_points": ["A simple stock list with a minimum level for each item", "Check usage regularly and reorder before the minimum", "Store items in labelled places and record what goes out", "A backup supplier for critical items"], "source_url": null, "sort_order": 5},
{"id": "41625889-460f-588b-b62f-95f1b4ba3ccf", "role": "operations-executive", "kind": "role", "difficulty": "medium", "category": "Problem solving", "question": "Load shedding stops a key machine or system for three hours on a busy day. What do you do?", "key_points": ["Switch to backup: generator, UPS or a manual process", "Tell customers and staff about delays honestly", "Do the most urgent work first", "Afterwards, check the backup plan and fuel, and fix gaps"], "source_url": null, "sort_order": 6},
{"id": "d326e4cf-9115-5701-970b-a57bafb6d156", "role": "operations-executive", "kind": "role", "difficulty": "medium", "category": "Scheduling", "question": "Two staff call in sick on the busiest day before Eid. How do you cover the work?", "key_points": ["Decide which work must be done today", "Move people from less urgent tasks, or call in staff with fair overtime", "Warn customers early about any delay", "Review the roster plan for peak days"], "source_url": null, "sort_order": 7},
{"id": "80310b6b-a426-5ea5-8f04-694d2a66a195", "role": "operations-executive", "kind": "role", "difficulty": "medium", "category": "Service quality", "question": "Your team lost a customer's booking and you are fully booked. What do you do?", "key_points": ["Apologise and take responsibility for the team", "Find an option: a partner venue, a later slot or an upgrade", "Offer fair compensation within policy", "Find out why the booking was lost and fix the process"], "source_url": null, "sort_order": 8},
{"id": "d0ae2b9b-4291-56c5-ae57-674bd3043014", "role": "operations-executive", "kind": "role", "difficulty": "medium", "category": "Process", "question": "A process has too many steps and customers wait too long. How would you improve it?", "key_points": ["Map the steps and time each one", "Remove steps that add no value, and run some side by side", "Test the change on a small scale", "Measure waiting time before and after"], "source_url": null, "sort_order": 9},
{"id": "00434cd2-a23b-5c62-8995-607e00612579", "role": "operations-executive", "kind": "role", "difficulty": "medium", "category": "People", "question": "A vendor often delivers late, which delays your team. How do you deal with it?", "key_points": ["Record each delay with dates and its effect", "Talk to the vendor with the data and agree a fix", "Use the contract terms if needed", "Line up a backup vendor for critical items"], "source_url": null, "sort_order": 10},
{"id": "319e3e96-603b-56c7-b798-1fe08f6c0f61", "role": "operations-executive", "kind": "role", "difficulty": "hard", "category": "Problem solving", "question": "Dhaka traffic makes your team late to client sites every morning. How do you solve it?", "key_points": ["Look at the data: which routes, times and teams", "Change start times, routes or the order of visits", "Base staff nearer to clients where possible", "Give clients realistic times and track if it improves"], "source_url": null, "sort_order": 11},
{"id": "6c049667-78c8-59b8-8a40-58f9137e88e3", "role": "operations-executive", "kind": "role", "difficulty": "hard", "category": "People", "question": "Two experienced team members refuse to follow a new process you introduced. What do you do?", "key_points": ["Listen to their reasons: they may see a real problem", "Explain why the change matters, with data", "Involve them in improving the process", "If they still refuse, follow the normal process with your manager"], "source_url": null, "sort_order": 12},
{"id": "46e99e90-7abd-5584-a07c-ad6586d808e9", "role": "operations-executive", "kind": "role", "difficulty": "hard", "category": "Reporting", "question": "Your daily numbers look good, but customer complaints are rising. What do you check?", "key_points": ["Whether the measures match what customers care about", "Read the complaints and group them by cause", "Look for gaps in quality, waiting time or staff behaviour", "Add a measure for the real problem and act on it"], "source_url": null, "sort_order": 13},
{"id": "2d222835-b395-5bf8-9c38-20156cf97eb0", "role": "operations-executive", "kind": "role", "difficulty": "hard", "category": "Process", "question": "You have one week to plan operations for an event with two thousand guests. How do you start?", "key_points": ["Split the work: venue, food, transport, safety and staff", "A timeline with an owner and a date for every task", "Confirm vendors in writing and line up backups", "Plan for rain, power cuts and crowd safety"], "source_url": null, "sort_order": 14},
{"id": "6fc4674b-c68b-5788-908e-f1d59922c7e4", "role": "operations-executive", "kind": "role", "difficulty": "hard", "category": "Service quality", "question": "A mistake by your team caused a serious problem for an important client. How do you handle it?", "key_points": ["Tell the client quickly and honestly, and take ownership", "Fix the immediate problem first", "Find the root cause and change the process", "Follow up with the client on what changed"], "source_url": null, "sort_order": 15},
{"id": "54d44a46-2473-5c73-88d0-379a432ba6ff", "role": "sales-executive", "kind": "role", "difficulty": "easy", "category": "Primary and secondary sales", "question": "What is the difference between primary sales and secondary sales?", "key_points": ["Primary: the company sells to the distributor", "Secondary: the distributor sells to retailers", "Sales from the retailer to the consumer come after that", "Secondary sales show real demand in the market"], "source_url": null, "sort_order": 1},
{"id": "d48fef99-193f-5ef2-be85-bd5b851e2290", "role": "sales-executive", "kind": "role", "difficulty": "easy", "category": "Sales basics", "question": "Sell this pen to me.", "key_points": ["Asks questions first to learn what I need", "Links one or two features to that need", "Handles a doubt calmly", "Asks for the order clearly"], "source_url": null, "sort_order": 2},
{"id": "328293ca-986d-5430-b656-c93da5c4d2cf", "role": "sales-executive", "kind": "role", "difficulty": "easy", "category": "Territory and routes", "question": "What is a beat plan, and why does a sales officer need one?", "key_points": ["A fixed plan of which shops to visit on which day", "Covers every outlet at the right frequency", "Saves travel time and cost", "Lets the manager check coverage"], "source_url": null, "sort_order": 3},
{"id": "1c5a95b0-e204-5852-ab45-87932737f5d7", "role": "sales-executive", "kind": "role", "difficulty": "easy", "category": "Distributors", "question": "What does a distributor do for a company?", "key_points": ["Buys stock from the company and stores it locally", "Delivers to retailers and collects payment", "Gives credit to shops and handles returns", "Provides staff and vans for the territory"], "source_url": null, "sort_order": 4},
{"id": "d775a03c-0829-5b84-b5db-fe8a621bf046", "role": "sales-executive", "kind": "role", "difficulty": "easy", "category": "Reporting", "question": "What information would you report at the end of a sales day?", "key_points": ["Outlets visited and orders taken against the plan", "New shops opened and shops lost", "Stock levels and competitor activity seen in the market", "Problems that need the manager's help"], "source_url": null, "sort_order": 5},
{"id": "867f8e9f-c1a4-54a9-8795-999c1528021f", "role": "sales-executive", "kind": "role", "difficulty": "medium", "category": "Negotiation", "question": "A shopkeeper wants more credit before paying the last bill. How do you handle it?", "key_points": ["Check the shop's payment record and current dues", "Explain the credit policy politely and firmly", "Offer options: a smaller order, part payment now, or a payment date", "Keep the relationship while protecting the company"], "source_url": null, "sort_order": 6},
{"id": "da09ecb3-9b6b-53a6-9c6e-36cb7b98f413", "role": "sales-executive", "kind": "role", "difficulty": "medium", "category": "Targets", "question": "It is the 20th of the month and you are far behind target. What do you do?", "key_points": ["Find where the gap is: products, outlets or areas", "Focus on high-potential outlets and fast-moving products", "Use the schemes available without pushing stock shops cannot sell", "Tell the manager early, with a plan"], "source_url": null, "sort_order": 7},
{"id": "25cac757-693f-5a3e-8832-fd38e13e6e03", "role": "sales-executive", "kind": "role", "difficulty": "medium", "category": "Territory and routes", "question": "How would you cover a new rural territory with many small markets and haats?", "key_points": ["Map the markets, haat days and key shops", "Plan visits around haat days", "Appoint or support a sub-distributor where needed", "Track coverage and orders by market"], "source_url": null, "sort_order": 8},
{"id": "9bca8759-5cd3-5f0d-a2fc-0697519b935e", "role": "sales-executive", "kind": "role", "difficulty": "medium", "category": "Distributors", "question": "Your distributor is not delivering to small shops on time. What do you do?", "key_points": ["Check delivery records and talk to the retailers", "Find the cause: vans, staff, money or stock", "Agree a fix and a timeline with the distributor", "Escalate to the manager if it does not improve"], "source_url": null, "sort_order": 9},
{"id": "1209831d-5001-50cd-b889-fd1aba56a2a7", "role": "sales-executive", "kind": "role", "difficulty": "medium", "category": "Sales basics", "question": "A retailer says a competitor gives a better margin. How do you respond?", "key_points": ["Ask exactly what the offer is", "Show the value of your product: faster sales, brand demand, support", "Compare total profit for the shop, not only margin per piece", "Report the competitor's offer to the manager"], "source_url": null, "sort_order": 10},
{"id": "f03f8796-230a-5bd3-a5c4-76216d8f9a8a", "role": "sales-executive", "kind": "role", "difficulty": "hard", "category": "Ethics", "question": "Your manager asks you to push extra stock to a distributor at month end to hit target, knowing it will not sell. What do you do?", "key_points": ["Explain the risk: returns, expired stock and an unhappy distributor", "Suggest real ways to close the gap", "Never hide it in reports", "Raise it with the right person if the pressure continues"], "source_url": null, "sort_order": 11},
{"id": "f3213db7-d12d-5aa1-8170-40b0188372da", "role": "sales-executive", "kind": "role", "difficulty": "hard", "category": "Primary and secondary sales", "question": "Primary sales are high but secondary sales are falling. What does this tell you, and what would you do?", "key_points": ["Stock is piling up at the distributor instead of reaching shops", "Risk of returns, discounts and expiry later", "Find why shops are not buying: price, competition or coverage", "Ease the primary push and fix the market problem"], "source_url": null, "sort_order": 12},
{"id": "6235e9d6-fcf9-5e48-af1d-fcd14afcf279", "role": "sales-executive", "kind": "role", "difficulty": "hard", "category": "Negotiation", "question": "A large retailer wants a special discount that company policy does not allow. How do you handle it?", "key_points": ["Understand what they really need", "Offer what policy allows: display support, schemes, better service", "Ask the manager about an exception only if the numbers justify it", "Never promise what you cannot give"], "source_url": null, "sort_order": 13},
{"id": "a92834cc-b13b-5d06-b009-5b1bb20d5c84", "role": "sales-executive", "kind": "role", "difficulty": "hard", "category": "Targets", "question": "Your territory's sales fell after a flood. How would you rebuild them?", "key_points": ["Check which shops have reopened and what they need first", "Offer support allowed by policy, such as flexible credit or replacing damaged stock", "Focus on essential products people need now", "Rebuild the beat plan as roads and markets reopen"], "source_url": null, "sort_order": 14},
{"id": "d2e0931a-54a4-5419-b9aa-ca43fb2211db", "role": "sales-executive", "kind": "role", "difficulty": "hard", "category": "Reporting", "question": "How would you use sales data to find the outlets with the most growth potential?", "key_points": ["Compare each outlet with similar outlets nearby", "Look for range gaps: products they do not stock yet", "Rank outlets by potential and plan visits", "Track whether the extra effort brings growth"], "source_url": null, "sort_order": 15},
{"id": "d5cf442d-e38b-5dc5-8108-8edc6ab3e194", "role": "supply-chain-analyst", "kind": "role", "difficulty": "easy", "category": "Inventory", "question": "What is safety stock, and why do we keep it?", "key_points": ["Extra stock that covers uncertain demand or late supply", "Prevents stock-outs that lose sales", "Too much ties up cash and space", "Set it from lead time, demand changes and the service level wanted"], "source_url": null, "sort_order": 1},
{"id": "592ccbb8-2cb0-5996-947b-4764fe5107a8", "role": "supply-chain-analyst", "kind": "role", "difficulty": "easy", "category": "Procurement", "question": "What is a comparative statement, and why is it used in purchasing?", "key_points": ["A table comparing quotations from several suppliers", "Compares price, quality, delivery time, payment terms and warranty", "Supports a fair choice that is written down", "The lowest price is not always the best value"], "source_url": null, "sort_order": 2},
{"id": "2e7a8166-bc7c-519f-843c-d00cfc39a16d", "role": "supply-chain-analyst", "kind": "role", "difficulty": "easy", "category": "Inventory", "question": "What is the difference between FIFO and FEFO, and when does FEFO matter?", "key_points": ["FIFO: first in, first out", "FEFO: first expiry, first out", "FEFO matters for medicines, food and anything with a shelf life", "It cuts waste and stops expired stock reaching customers"], "source_url": null, "sort_order": 3},
{"id": "93cff984-7585-5d4b-80a4-f91dd8210765", "role": "supply-chain-analyst", "kind": "role", "difficulty": "easy", "category": "Logistics", "question": "What does a C&F agent do for an importer?", "key_points": ["Clears goods through customs on the importer's behalf", "Prepares and submits documents and pays duties for the importer", "Arranges release from the port and onward transport", "A good agent avoids delays and port storage charges"], "source_url": null, "sort_order": 4},
{"id": "79c6b3d7-b5e3-5dd5-b6d7-1f0e36ea3bce", "role": "supply-chain-analyst", "kind": "role", "difficulty": "easy", "category": "KPIs", "question": "What does on time in full mean, and why is it a useful measure?", "key_points": ["An order delivered on the agreed date with the full quantity", "Measures service from the customer's view", "Shows whether the problem is timing or quantity", "Track it by supplier, route and product"], "source_url": null, "sort_order": 5},
{"id": "22a2e38e-e40e-5ae5-bdc9-c79eec86e1be", "role": "supply-chain-analyst", "kind": "role", "difficulty": "medium", "category": "Forecasting", "question": "How would you forecast demand for a product before Eid?", "key_points": ["Use past Eid sales, adjusted for the date moving each year", "Add current trends, promotions and price changes", "Ask sales teams and key distributors", "Plan production and transport early, with a review point"], "source_url": null, "sort_order": 6},
{"id": "d9613eff-13fb-5bc1-aea7-54cc2359437b", "role": "supply-chain-analyst", "kind": "role", "difficulty": "medium", "category": "Logistics", "question": "An imported shipment is stuck at Chattogram port and production needs it next week. What do you do?", "key_points": ["Find the exact cause with the C&F agent: documents, testing, duty or congestion", "Fix document problems fast and escalate to the right office", "Plan B: air freight for part of it, a local supplier, or a new production plan", "Tell production and sales early and update them daily"], "source_url": null, "sort_order": 7},
{"id": "ce2e1677-319b-55de-a470-d89fd4a3dff6", "role": "supply-chain-analyst", "kind": "role", "difficulty": "medium", "category": "Inventory", "question": "What is ABC analysis, and how would you use it in a warehouse?", "key_points": ["Groups items by value: A high, B medium, C low", "Control A items tightly with frequent counts and good forecasts", "Simpler control for C items", "Use it to plan counts, space and supplier focus"], "source_url": null, "sort_order": 8},
{"id": "4394eab7-e6f1-57c5-9d7b-71d920afdbb1", "role": "supply-chain-analyst", "kind": "role", "difficulty": "medium", "category": "Warehousing", "question": "Warehouse records show stock that cannot be found on the shelves. How do you find out what happened?", "key_points": ["Recount and check bin locations and recent moves", "Check receiving, issue and return records for errors", "Look for patterns: the same items, shifts or people", "Fix the process and adjust records with approval"], "source_url": null, "sort_order": 9},
{"id": "63eac4f6-4b38-5604-a664-04d676c53139", "role": "supply-chain-analyst", "kind": "role", "difficulty": "medium", "category": "Data", "question": "How would you use Excel to find slow-moving items in a list of a few thousand products?", "key_points": ["Calculate days of stock or time since the last movement", "Use pivot tables or filters by category and location", "Agree a clear rule for 'slow' with the team", "Share a short list with actions: discount, transfer or stop buying"], "source_url": null, "sort_order": 10},
{"id": "5daa7136-d8f1-5e82-a083-2d1580158b88", "role": "supply-chain-analyst", "kind": "role", "difficulty": "hard", "category": "Logistics", "question": "Lead time for an imported raw material has grown from six weeks to ten. What do you change?", "key_points": ["Raise the reorder point and safety stock for that item", "Order earlier and plan LC opening with finance", "Look for a second supplier, possibly a local one", "Explain the cash cost of holding more stock"], "source_url": null, "sort_order": 11},
{"id": "ef7c23ec-55f6-51be-906d-1ba275f9eac9", "role": "supply-chain-analyst", "kind": "role", "difficulty": "hard", "category": "Forecasting", "question": "Your forecast was badly wrong last month. How do you explain it and improve?", "key_points": ["Measure the error and find where it came from: product, area or channel", "Check one-off causes: a promotion, a strike, a flood, a stock-out", "Adjust the method and add input from sales", "Report honestly and track accuracy over time"], "source_url": null, "sort_order": 12},
{"id": "415122f7-39da-5c7a-a0e5-f088b1acd6ae", "role": "supply-chain-analyst", "kind": "role", "difficulty": "hard", "category": "Logistics", "question": "Monsoon flooding and a transport strike hit in the same week. How do you keep supply moving?", "key_points": ["Decide which customers and products matter most", "Move stock to safe depots before roads close", "Use other routes or modes: rail, river or smaller vehicles", "Share a daily plan with everyone affected"], "source_url": null, "sort_order": 13},
{"id": "3b4accdd-51dd-5e1a-9d68-5973efe2bbc0", "role": "supply-chain-analyst", "kind": "role", "difficulty": "hard", "category": "Procurement", "question": "The lowest bidder has a poor delivery record, and your manager wants the lowest price. What do you recommend?", "key_points": ["Compare total cost: delays, quality problems and lost sales", "Show the supplier's past record with data", "Options: split the order, add penalty terms or place a trial order", "Record the decision and the reasons"], "source_url": null, "sort_order": 14},
{"id": "cbfb2a60-cecc-57fb-a4ed-ea086cbf5703", "role": "supply-chain-analyst", "kind": "role", "difficulty": "hard", "category": "Warehousing", "question": "Medicines must stay cold from the warehouse to pharmacies outside Dhaka. How would you monitor the cold chain?", "key_points": ["Temperature loggers in storage and vehicles, checked at each hand-over", "Clear limits and steps to follow when they are crossed", "Backup power for cold rooms during load shedding", "Track every temperature breach and fix the weak link"], "source_url": null, "sort_order": 15},
{"id": "6f5be0a2-225a-5772-81d2-1693159f575a", "role": "accountant", "kind": "role", "difficulty": "easy", "category": "Fundamentals", "question": "What is the difference between cash and accrual accounting?", "key_points": ["Cash basis records income and costs when money moves", "Accrual basis records them when they are earned or owed", "Accrual shows the true result for the period and is used for financial statements", "Example: a credit sale in June counts in June under accrual"], "source_url": null, "sort_order": 1},
{"id": "cd1e6414-4fee-59b8-a3e0-29519de8c3b7", "role": "accountant", "kind": "role", "difficulty": "easy", "category": "Fundamentals", "question": "Explain debit and credit to somebody who has never studied accounting.", "key_points": ["Every transaction has two sides that must balance", "Debits increase assets and expenses", "Credits increase liabilities, equity and income", "Uses a simple example, such as buying stock for cash"], "source_url": null, "sort_order": 2},
{"id": "5dea211a-de77-578b-b9a9-d6217c8db7fa", "role": "accountant", "kind": "role", "difficulty": "easy", "category": "Statements", "question": "What is on a balance sheet, and what is not?", "key_points": ["Assets, liabilities and equity on one date", "Not sales or expenses for the year: they go in the income statement", "Some things of value are often missing, such as staff skills or a home-grown brand", "It must balance: assets equal liabilities plus equity"], "source_url": null, "sort_order": 3},
{"id": "3dcbbb7a-f5ab-5451-9c11-caff2190db17", "role": "accountant", "kind": "role", "difficulty": "medium", "category": "Reconciliation", "question": "The bank statement does not match the ledger. How do you find the difference?", "key_points": ["Prepare a bank reconciliation from both closing balances", "Timing items: cheques not yet presented, deposits not yet credited", "Items only the bank knows: charges, profit or interest, returned cheques", "Errors on either side, then correct the ledger and have it checked"], "source_url": null, "sort_order": 4},
{"id": "a5fcb9fc-ecf7-5d17-adb7-9e8d422d5ba5", "role": "accountant", "kind": "role", "difficulty": "medium", "category": "VAT and tax", "question": "What is VAT, and how does it work in Bangladesh?", "key_points": ["A tax on the value added at each stage, carried in the end by the consumer", "Registered businesses charge output VAT and claim credit for input VAT", "Under the VAT and SD Act 2012: a Mushak 6.3 invoice per sale and a monthly return", "Check current rates and SROs on the NBR website before quoting any"], "source_url": "https://nbr.gov.bd/", "sort_order": 5},
{"id": "8f1b77b9-a826-530d-8b30-c8c4d981f21b", "role": "accountant", "kind": "role", "difficulty": "medium", "category": "Closing the books", "question": "An invoice arrives after year end. What do you do with it?", "key_points": ["Check the date the goods or service were received, not the invoice date", "If it belongs to last year, accrue it in last year's accounts", "If the books are closed, judge if it is material and ask a senior or the auditor", "Improve the cut-off check so it is caught next time"], "source_url": null, "sort_order": 6},
{"id": "d9d9ab59-a5ae-5495-b186-93cebe4cd633", "role": "accountant", "kind": "role", "difficulty": "hard", "category": "Closing the books", "question": "Take me through closing the books for a month.", "key_points": ["Post all entries, accruals, prepayments and depreciation", "Reconcile bank, receivables, payables and stock", "Review the trial balance and look into odd balances", "Prepare reports on time and list open items"], "source_url": null, "sort_order": 7},
{"id": "d5052d93-6cfb-56e9-aa08-0403a282b67a", "role": "accountant", "kind": "role", "difficulty": "hard", "category": "Ethics", "question": "A manager asks you to record something you believe is wrong. What do you do?", "key_points": ["Ask what the entry is for and what evidence supports it", "Explain the rule or standard calmly, in writing if needed", "Do not record it without support; escalate to the finance head or audit", "Keep notes, because your name is on the entry"], "source_url": null, "sort_order": 8},
{"id": "0bbe9f52-a706-590a-b384-e84b612bfe74", "role": "accountant", "kind": "role", "difficulty": "hard", "category": "Communication", "question": "Explain a cash flow problem to somebody who is not an accountant.", "key_points": ["Profit is not cash: a profitable business can still run out of money", "Simple example: sales on credit while suppliers want cash", "Show when money comes in and goes out, week by week", "Suggest actions: collect faster, plan payments, arrange short-term finance"], "source_url": null, "sort_order": 9},
{"id": "59917c31-c774-574a-b0a2-3c6f50b3f5c1", "role": "accountant", "kind": "role", "difficulty": "easy", "category": "Software", "question": "Which accounting software have you used, and how do you avoid mistakes when entering data?", "key_points": ["Names the tool honestly: Tally, an ERP or Excel", "Uses the right ledgers and voucher types, with a clear narration", "Checks entries against source documents and runs reports to spot errors", "Keeps backups and never shares a log-in"], "source_url": null, "sort_order": 10},
{"id": "ba7a2d3f-dfbf-5d96-9429-5f29ec86bfc1", "role": "accountant", "kind": "role", "difficulty": "easy", "category": "Statements", "question": "What is depreciation, and why do we charge it?", "key_points": ["Spreads the cost of an asset over the years it is used", "Matches the cost with the income the asset helps to earn", "Common methods: straight line and reducing balance", "No cash leaves, so it is added back in the cash flow statement"], "source_url": null, "sort_order": 11},
{"id": "10b9ef20-4832-57cf-b550-fd4e394bab83", "role": "accountant", "kind": "role", "difficulty": "medium", "category": "VAT and tax", "question": "What are VDS and TDS, and what do you check before paying a supplier's bill?", "key_points": ["VDS: VAT deducted at source by a withholding entity under the VAT law", "TDS: income tax deducted at source under the Income Tax Act 2023", "Check the supplier's BIN or TIN, the Mushak 6.3 invoice and the current rate for that service", "Deposit the amounts on time and give the supplier a certificate"], "source_url": "https://nbr.gov.bd/", "sort_order": 12},
{"id": "e76815a8-9e33-529a-a580-264871a9f6a5", "role": "accountant", "kind": "role", "difficulty": "medium", "category": "Reconciliation", "question": "A supplier says we owe them more than our ledger shows. How do you sort it out?", "key_points": ["Get their statement and match it line by line with our ledger", "Common causes: missing invoices, payments in transit, returns, tax deducted at source", "Agree each difference in writing and correct the side that is wrong", "Do not pay the extra until the difference is explained"], "source_url": null, "sort_order": 13},
{"id": "200d1181-79c6-5959-b9dd-5e2c4e8b39e8", "role": "accountant", "kind": "role", "difficulty": "hard", "category": "VAT and tax", "question": "The company's income tax return is due and some expense bills have no proper documents. What do you do?", "key_points": ["Expenses without proper evidence may not be allowed for tax, so list them", "Try to get proper invoices or evidence from the suppliers now", "Tell the manager early, with the list, the amounts and the tax effect", "Never create or change documents to fill the gap"], "source_url": "https://nbr.gov.bd/", "sort_order": 14},
{"id": "0de78a34-f4b2-519c-9fb0-9ff1a191eef9", "role": "accountant", "kind": "role", "difficulty": "hard", "category": "Statements", "question": "What changes for you when a company must follow IFRS, and where do you check the rules that apply in Bangladesh?", "key_points": ["IFRS sets how items are measured and shown, such as revenue, leases and assets", "Public interest entities follow the standards the FRC adopts under the Financial Reporting Act 2015", "Notes and disclosures need as much care as the numbers", "Check the FRC and ICAB websites for what applies now"], "source_url": "https://frc.gov.bd/", "sort_order": 15},
{"id": "f9e7b991-58cf-5118-9506-0df6fc063e0c", "role": "audit-associate", "kind": "role", "difficulty": "easy", "category": "Audit basics", "question": "What is the difference between external audit and internal audit?", "key_points": ["External audit gives an independent opinion on the financial statements", "Internal audit helps management check controls, risks and processes", "External auditors are appointed by shareholders and must be independent", "Internal audit reports to management or the audit committee"], "source_url": null, "sort_order": 1},
{"id": "af36734f-6f9a-517a-ad82-434e8e2dbd30", "role": "audit-associate", "kind": "role", "difficulty": "easy", "category": "Audit basics", "question": "Why do you want to do articleship, and what do you expect to learn?", "key_points": ["Real work with many clients and industries", "Audit procedures, accounting and tax in practice", "Honest about balancing exams and work", "Commitment to finishing the chartered accountancy route"], "source_url": "https://www.icab.org.bd/", "sort_order": 2},
{"id": "c26d042a-49a1-5fd7-b097-00925246a1dd", "role": "audit-associate", "kind": "role", "difficulty": "easy", "category": "Verification", "question": "How would you check that a company's cash balance at year end is correct?", "key_points": ["Get a confirmation directly from the bank", "Check the bank reconciliation and clear unusual items", "Count cash in hand on the date, with the cashier present", "Check the cut-off of receipts and payments around year end"], "source_url": null, "sort_order": 3},
{"id": "7363898f-120b-50f6-8762-7ef83d69c002", "role": "audit-associate", "kind": "role", "difficulty": "easy", "category": "Internal control", "question": "What is internal control? Give an example from a purchase process.", "key_points": ["Steps and checks that prevent or catch errors and fraud", "One person orders, another receives and a third approves payment", "Order, delivery note and invoice are matched before paying", "Controls only help if people follow them"], "source_url": null, "sort_order": 4},
{"id": "a7ba29f9-191f-5871-a642-bc6d8da319c1", "role": "audit-associate", "kind": "role", "difficulty": "easy", "category": "Working papers", "question": "What makes a good audit working paper?", "key_points": ["A clear purpose, source and the work done", "Enough detail for another auditor to repeat it", "A conclusion, with preparer, reviewer and date", "Cross-referenced to the statements and other papers"], "source_url": null, "sort_order": 5},
{"id": "7f967b19-43dc-5039-be6d-835dae6d3bdd", "role": "audit-associate", "kind": "role", "difficulty": "medium", "category": "Risk and materiality", "question": "What is materiality, and how does it change what you test?", "key_points": ["A misstatement is material if it could change a user's decision", "Set at planning from a base such as profit or revenue", "Higher-risk areas get more testing", "Small errors still matter if they are fraud or add up"], "source_url": null, "sort_order": 6},
{"id": "fe902589-1c05-5e67-b851-1b84a12f9d04", "role": "audit-associate", "kind": "role", "difficulty": "medium", "category": "Sampling", "question": "How would you choose a sample of sales invoices to test?", "key_points": ["Define what you are testing and the population", "Use random or systematic selection, plus large or unusual items", "Sample size depends on risk and on the controls", "Record how the sample was chosen"], "source_url": null, "sort_order": 7},
{"id": "57ae734d-aa53-5b70-b559-1b484c11f46e", "role": "audit-associate", "kind": "role", "difficulty": "medium", "category": "Verification", "question": "At a stock count, the count does not match the records. What do you do?", "key_points": ["Recount a sample yourself and note each difference", "Look for reasons: cut-off, damaged goods, record errors", "Report the differences to the client and your senior", "Follow up the adjustments before sign-off"], "source_url": null, "sort_order": 8},
{"id": "d89a6bf1-d2d5-5ad3-91bc-22a36ee4f43f", "role": "audit-associate", "kind": "role", "difficulty": "medium", "category": "Internal control", "question": "At a client with a lot of cash sales, what risks do you look for?", "key_points": ["Sales not recorded, or cash taken before it is banked", "Weak separation: the same person sells, counts and banks", "Compare daily cash reports with bank deposits", "Use surprise cash counts and compare margins across outlets"], "source_url": null, "sort_order": 9},
{"id": "a161728c-933b-5a22-8369-58fabd26d06e", "role": "audit-associate", "kind": "role", "difficulty": "medium", "category": "Verification", "question": "How do you check VAT and tax figures as part of a statutory audit?", "key_points": ["Reconcile VAT returns with the sales and purchase records", "Check that tax deducted at source was deposited on time", "Review tax provisions and any open assessments", "Use the current law and SROs from the NBR website"], "source_url": "https://nbr.gov.bd/", "sort_order": 10},
{"id": "ef32f4c3-1677-5268-a901-6115f4bd6acd", "role": "audit-associate", "kind": "role", "difficulty": "hard", "category": "Risk and materiality", "question": "Revenue grew much faster than cash collected this year. What risk does this suggest, and how do you test it?", "key_points": ["Risk of fake sales or sales recorded too early", "Check receipts after year end and any credit notes", "Confirm balances directly with customers", "Test cut-off around year end"], "source_url": null, "sort_order": 11},
{"id": "cde83167-d2e0-50e8-b8e8-8045ec65b3ab", "role": "audit-associate", "kind": "role", "difficulty": "hard", "category": "Independence", "question": "The finance manager at your audit client offers you a gift and a free trip. What do you do?", "key_points": ["Politely refuse, because it threatens independence", "Tell your senior or manager", "Follow the firm's rules and ICAB's code of ethics", "Keep the relationship with the client professional"], "source_url": "https://www.icab.org.bd/", "sort_order": 12},
{"id": "5a6fa4bf-c3cb-5bd0-8c53-f4de936b659c", "role": "audit-associate", "kind": "role", "difficulty": "hard", "category": "Working papers", "question": "Your senior asks you to sign off a test you could not finish because the client did not give documents. What do you do?", "key_points": ["Do not sign off work that was not done", "Record what was asked for, when, and what is missing", "Tell the senior clearly and suggest other procedures", "Note the limitation so the reviewer can decide"], "source_url": null, "sort_order": 13},
{"id": "7debfbcc-b535-5727-8088-2aea0e0193cb", "role": "audit-associate", "kind": "role", "difficulty": "hard", "category": "Audit basics", "question": "What does the FRC do in Bangladesh, and how does it affect auditors?", "key_points": ["An independent regulator set up under the Financial Reporting Act 2015", "Adopts accounting and auditing standards for public interest entities", "Monitors audit quality and can act against auditors", "Check FRC notices and the standards it has adopted"], "source_url": "https://frc.gov.bd/", "sort_order": 14},
{"id": "3685ca93-2458-5214-860d-a8c4117ef174", "role": "audit-associate", "kind": "role", "difficulty": "hard", "category": "Risk and materiality", "question": "Near the deadline you find a large unrecorded liability, and the client says it is too late to change the accounts. What happens next?", "key_points": ["Measure it against materiality", "Tell the senior and the engagement partner at once", "Ask the client to adjust, and explain the effect on the opinion if they refuse", "Record everything in the working papers"], "source_url": null, "sort_order": 15},
{"id": "7d69c784-dafc-5c04-8318-e5bcac841960", "role": "market-research-analyst", "kind": "role", "difficulty": "easy", "category": "Research design", "question": "What is the difference between primary and secondary research? Give an example of each.", "key_points": ["Primary: data you collect yourself, such as a survey or interviews", "Secondary: data others collected, such as BBS reports or industry studies", "Start with secondary research to learn what is already known", "Use primary research to fill the gap for your exact question"], "source_url": null, "sort_order": 1},
{"id": "597a6ada-731a-5e63-bad8-dc1bd20ca59d", "role": "market-research-analyst", "kind": "role", "difficulty": "easy", "category": "Research design", "question": "What is the difference between qualitative and quantitative research?", "key_points": ["Qualitative: why and how, from interviews and group discussions", "Quantitative: how many and how much, from surveys and data", "Qualitative work often comes first to shape the survey", "Good studies often use both"], "source_url": null, "sort_order": 2},
{"id": "a7c5a0ba-b27f-5029-82b1-168b42f04ee5", "role": "market-research-analyst", "kind": "role", "difficulty": "easy", "category": "Research design", "question": "Where would you look for secondary data on a market in Bangladesh, such as exports of one product?", "key_points": ["Official statistics, such as BBS and the Export Promotion Bureau", "International trade databases for the buying countries", "Industry associations, company reports and trade press", "Check the date, definition and source of every figure"], "source_url": null, "sort_order": 3},
{"id": "cba1fc5c-790f-5b08-b859-78b85ee72ef7", "role": "market-research-analyst", "kind": "role", "difficulty": "easy", "category": "Questionnaires", "question": "What makes a survey question bad? Give an example.", "key_points": ["Leading questions that push people towards an answer", "Two questions in one", "Words people do not know, or that change meaning in translation", "Answer options that overlap or miss common answers"], "source_url": null, "sort_order": 4},
{"id": "e3574c6a-49db-5990-9d9b-598ea4307aa6", "role": "market-research-analyst", "kind": "role", "difficulty": "easy", "category": "Data analysis", "question": "What are the mean, median and mode, and which would you use for household income?", "key_points": ["Mean: the average; median: the middle value; mode: the most common", "Income is pulled up by a few very rich households", "The median gives a fairer picture of a typical household", "Report the spread too, not one number alone"], "source_url": null, "sort_order": 5},
{"id": "15b71d48-7543-54f2-bc87-530ad504c703", "role": "market-research-analyst", "kind": "role", "difficulty": "medium", "category": "Sampling", "question": "You need to survey shops in both urban and rural areas of a division. How would you choose the sample?", "key_points": ["Define the population and find or build a list of shops", "Split by urban and rural so both are covered", "Pick randomly within each group, often in clusters to save travel", "Set the sample size from the precision needed and the budget"], "source_url": null, "sort_order": 6},
{"id": "819d4aba-6649-5362-b45f-f9ac62a62390", "role": "market-research-analyst", "kind": "role", "difficulty": "medium", "category": "Questionnaires", "question": "Your questionnaire is in English and the field team will ask it in Bangla. How do you make sure it means the same thing?", "key_points": ["Translate it, then have another person translate it back", "Use everyday Bangla, with local words where needed", "Pre-test with a few real respondents and fix confusing questions", "Train enumerators on what each question means"], "source_url": null, "sort_order": 7},
{"id": "58503c92-3187-5fd0-8f27-41ea9188ec12", "role": "market-research-analyst", "kind": "role", "difficulty": "medium", "category": "Field work", "question": "Halfway through a survey, one enumerator's interviews are much shorter than everyone else's. What do you do?", "key_points": ["Check the data: timing, GPS and repeated answer patterns", "Back-check some respondents by phone or a visit", "Talk to the enumerator, then retrain or replace them", "Redo or remove bad interviews and note it in the report"], "source_url": null, "sort_order": 8},
{"id": "f26eb422-268a-589d-8914-22c498a56145", "role": "market-research-analyst", "kind": "role", "difficulty": "medium", "category": "Data analysis", "question": "How would you check whether rural households spend more on mobile data than urban households?", "key_points": ["Compare averages and medians by area, with sample sizes", "Test whether the difference is statistically significant", "Control for other factors, such as income and household size", "Show the result in a simple table or chart"], "source_url": null, "sort_order": 9},
{"id": "12714699-9f48-5682-b3f9-0ac0547edc2d", "role": "market-research-analyst", "kind": "role", "difficulty": "medium", "category": "Ethics", "question": "How do you get informed consent in a household survey, and what if the person cannot read?", "key_points": ["Explain the purpose, the time needed and that taking part is voluntary", "Say how their answers will be kept private", "Read the consent aloud and record verbal consent where allowed", "They can skip a question or stop at any time"], "source_url": null, "sort_order": 10},
{"id": "d3f588dc-5cde-538e-9264-36f6784a5273", "role": "market-research-analyst", "kind": "role", "difficulty": "hard", "category": "Research design", "question": "A client wants to know if farmers will pay more for a new seed variety. How would you design the study?", "key_points": ["Define what to measure: willingness to pay, current costs and yields, who decides", "Start with group discussions in a few districts, then run a survey", "Ask about real behaviour and trade-offs, not only 'would you buy'", "Consider a demonstration plot to see real choices"], "source_url": null, "sort_order": 11},
{"id": "d240486e-4280-5418-a7b8-9e150fb501f4", "role": "market-research-analyst", "kind": "role", "difficulty": "hard", "category": "Data analysis", "question": "Your survey shows average household income in an area far above official BBS figures. What do you do?", "key_points": ["Check the sample: did it miss poorer households or areas", "Check question wording and the time period asked about", "Look for data entry errors and outliers", "Explain the gap honestly in the report"], "source_url": null, "sort_order": 12},
{"id": "2f68d8e2-cd22-5ff2-97a4-c0e5ab3694e0", "role": "market-research-analyst", "kind": "role", "difficulty": "hard", "category": "Reporting", "question": "How would you present survey results to a manager who has five minutes and does not like statistics?", "key_points": ["Start with three key findings and what to do about them", "Use simple charts and round numbers", "Say how sure you are and the main limits", "Put tables and methods in an annex"], "source_url": null, "sort_order": 13},
{"id": "af53c664-0a49-5c5f-b7b0-50aa738e0f98", "role": "market-research-analyst", "kind": "role", "difficulty": "hard", "category": "Field work", "question": "Floods hit two of your survey districts during field work. How do you manage the study?", "key_points": ["Keep the team safe first and pause where needed", "Tell the client early about the delay and the options", "Reschedule or replace the sample by a fair rule, and record it", "Think about whether the flood changes the answers, and note it"], "source_url": null, "sort_order": 14},
{"id": "38268833-8fdb-56f2-8c6d-7551b3065b06", "role": "market-research-analyst", "kind": "role", "difficulty": "hard", "category": "Ethics", "question": "A client asks you to drop some survey responses because they do not support the result they want. What do you do?", "key_points": ["Explain that removing valid data makes the result untrue", "Offer honest options: more analysis, a bigger sample or clear caveats", "Remove data only for recorded quality reasons", "Go to your manager if the pressure continues"], "source_url": null, "sort_order": 15},
{"id": "3a0c1ce2-6e28-5e16-8b16-df55b5393779", "role": "banking-officer", "kind": "role", "difficulty": "easy", "category": "Banking basics", "question": "What is the difference between a savings account and a current account?", "key_points": ["Savings: for individuals to keep money and earn some profit", "Current: for businesses and frequent transactions; usually no profit is paid", "Fees and minimum balance rules differ by bank"], "source_url": null, "sort_order": 1},
{"id": "cdab4529-fcfb-539c-ba0b-b20acb31260a", "role": "banking-officer", "kind": "role", "difficulty": "easy", "category": "Banking basics", "question": "What does Bangladesh Bank do?", "key_points": ["It is the central bank: it issues currency and sets monetary policy", "It licenses, regulates and supervises banks through circulars", "It runs the payment systems banks use to clear cheques and move money", "It manages the foreign exchange reserves"], "source_url": "https://www.bb.org.bd/", "sort_order": 2},
{"id": "e82bc096-e025-5469-82e6-0755574f8cac", "role": "banking-officer", "kind": "role", "difficulty": "easy", "category": "Accounts and KYC", "question": "What is KYC, and why does a bank need it before opening an account?", "key_points": ["Know your customer: confirm who the person is and how they will use the account", "Collect and check the NID, photo, address, source of funds and nominee", "It helps stop fraud and money laundering, and it is a legal duty"], "source_url": "https://www.bfiu.org.bd/", "sort_order": 3},
{"id": "9f022e7b-26b4-57d2-856d-dfaf4aeed104", "role": "banking-officer", "kind": "role", "difficulty": "easy", "category": "Customer service", "question": "A customer is angry because their cheque was returned. How do you handle it at the desk?", "key_points": ["Stay calm, listen and say sorry for the trouble without blaming anyone", "Find the reason: balance, signature, date, or words and figures not matching", "Explain the reason simply and what they can do next", "Keep their details private and escalate if needed"], "source_url": null, "sort_order": 4},
{"id": "59795705-424e-563c-851b-f5b877f50427", "role": "banking-officer", "kind": "role", "difficulty": "easy", "category": "Banking basics", "question": "What is the difference between a bank account and a mobile financial service wallet?", "key_points": ["A bank takes deposits, gives loans and offers full accounts", "A wallet lets people send, receive and pay from a phone, with lower limits", "Both are regulated by Bangladesh Bank", "Wallets reach people far from branches"], "source_url": "https://www.bb.org.bd/", "sort_order": 5},
{"id": "ff9ec5e6-f03b-5a32-ab9d-b88f635d351e", "role": "banking-officer", "kind": "role", "difficulty": "medium", "category": "Payments", "question": "What is the difference between BEFTN, RTGS and NPSB transfers?", "key_points": ["BEFTN: electronic transfers settled in batches, not instant", "RTGS: real-time transfers for high-value payments, in set hours", "NPSB: the interbank network for cards and instant online transfers", "Choose by amount, urgency and the channel the customer uses"], "source_url": null, "sort_order": 6},
{"id": "3bc25e40-0557-5387-8254-7b48627fd522", "role": "banking-officer", "kind": "role", "difficulty": "medium", "category": "Money laundering", "question": "What is money laundering, and what would make a transaction look suspicious to you?", "key_points": ["Making money from crime look clean: placement, layering, integration", "Red flags: activity that does not fit the customer, many deposits just under limits", "Report to the branch anti-money laundering officer, who reports to BFIU", "Never warn the customer"], "source_url": "https://www.bfiu.org.bd/", "sort_order": 7},
{"id": "443fb817-269e-5b51-b7e5-1d52e178f1be", "role": "banking-officer", "kind": "role", "difficulty": "medium", "category": "Accounts and KYC", "question": "A customer wants to open an account but has only a photocopy of their NID. What do you do?", "key_points": ["Follow the bank's KYC policy: the original must be seen and verified", "Banks check NID details online against the national ID database", "Explain politely what is needed and help them finish when they return", "Do not bend the rule, even for a known face"], "source_url": null, "sort_order": 8},
{"id": "8f2abd4a-54f8-5199-b538-1901a5a6b49e", "role": "banking-officer", "kind": "role", "difficulty": "medium", "category": "Credit basics", "question": "What is a classified or non-performing loan, and why does it matter to a bank?", "key_points": ["A loan unpaid past a set period is classified under Bangladesh Bank rules", "The bank must set money aside, which cuts profit and capital", "Prevention: careful checks before lending, including the CIB report, and early follow-up"], "source_url": "https://www.bb.org.bd/", "sort_order": 9},
{"id": "8c4b2c0d-97d7-5dbc-b1b2-08c99c6a704c", "role": "banking-officer", "kind": "role", "difficulty": "medium", "category": "Ethics", "question": "At the end of the day your cash is short by two thousand taka. What do you do?", "key_points": ["Do not quietly cover it from your own pocket", "Recount, and check every voucher, entry and log", "Tell the cash in-charge or manager at once and record it", "Find the cause so it does not happen again"], "source_url": null, "sort_order": 10},
{"id": "9387ecc2-b0b2-570d-aa4e-5845aadd12c5", "role": "banking-officer", "kind": "role", "difficulty": "hard", "category": "Banking basics", "question": "What are CRR and SLR, and how do they affect how much a bank can lend?", "key_points": ["CRR: the share of deposits kept as cash with Bangladesh Bank", "SLR: the share kept in safe, liquid assets such as government securities", "Both reduce the money available to lend", "Quote a rate only after checking the latest circular"], "source_url": "https://www.bb.org.bd/", "sort_order": 11},
{"id": "88ce16b8-7fc8-5d3a-b642-082d2deedfbd", "role": "banking-officer", "kind": "role", "difficulty": "hard", "category": "Banking basics", "question": "How is Islamic banking different from conventional banking? Explain one product.", "key_points": ["Islamic banks avoid interest and use profit-sharing or trade-based contracts", "Mudaraba: depositors share in the profit", "Murabaha: the bank buys the item and sells it on at an agreed mark-up", "A Shariah board approves the products"], "source_url": null, "sort_order": 12},
{"id": "64268b3f-54ad-5a3f-ad6e-aa8a3f052b49", "role": "banking-officer", "kind": "role", "difficulty": "hard", "category": "Ethics", "question": "A senior colleague asks you to process a large transfer without the usual documents, just this once. What do you do?", "key_points": ["Politely refuse to skip the process and explain the rule", "Offer to help get the documents quickly", "If the pressure continues, go to the manager or compliance", "The rules protect the customer, the bank and you"], "source_url": null, "sort_order": 13},
{"id": "2d9b2389-8e2d-5ad5-9280-70e4c8bb2b32", "role": "banking-officer", "kind": "role", "difficulty": "hard", "category": "Customer service", "question": "A customer says money left their account after they shared an OTP on a phone call. How do you help?", "key_points": ["Act fast: block the card or channel and log the complaint", "Raise a dispute or trace with the receiving bank or wallet", "Explain kindly, without blame, that the bank never asks for an OTP", "Report through the bank's fraud process and follow up"], "source_url": null, "sort_order": 14},
{"id": "46276d7f-1b56-5ca7-a1e8-f6ac51ccb02f", "role": "banking-officer", "kind": "role", "difficulty": "hard", "category": "Branch growth", "question": "How would you grow deposits at a branch in a district town?", "key_points": ["Know the area: traders, families receiving remittance, schools, small businesses", "Match products to them: savings schemes, remittance services, student accounts", "Go out to markets and schools, and ask happy customers for referrals", "Measure new accounts, deposit growth and cost"], "source_url": null, "sort_order": 15},
{"id": "c49f2d36-2b0a-557d-8a61-b859a07bbb7d", "role": "credit-analyst", "kind": "role", "difficulty": "easy", "category": "Financial statements", "question": "Which three financial statements would you ask a borrower for, and what does each tell you?", "key_points": ["Income statement: sales, costs and profit over a period", "Balance sheet: assets, debts and equity on one date", "Cash flow statement: where cash came from and where it went", "Ask for audited statements where possible and compare years"], "source_url": null, "sort_order": 1},
{"id": "4bee1bae-921b-5727-aecc-7469d0373e7e", "role": "credit-analyst", "kind": "role", "difficulty": "easy", "category": "Ratios", "question": "What is the current ratio, and what does a low one tell you?", "key_points": ["Current assets divided by current liabilities", "Shows whether the business can pay its short-term debts", "Low means it may struggle to pay suppliers or the bank on time", "Check the quality of current assets: old stock or old receivables are weak"], "source_url": null, "sort_order": 2},
{"id": "76faa96a-ef5a-50d4-9e89-f0edd9916b81", "role": "credit-analyst", "kind": "role", "difficulty": "easy", "category": "Credit risk", "question": "What are the five Cs of credit?", "key_points": ["Character, capacity, capital, collateral and conditions", "Capacity to repay from cash flow matters most", "Collateral is a backup, not the main way to be repaid", "Use them to structure the credit report"], "source_url": null, "sort_order": 3},
{"id": "27bc30a7-9650-5cd0-a41b-afc6a7c2b064", "role": "credit-analyst", "kind": "role", "difficulty": "easy", "category": "Loan types", "question": "What is the difference between a term loan and a working capital loan?", "key_points": ["Term loan: for long-term assets such as machines, repaid over years", "Working capital: for stock and receivables, short term and often renewed", "Match the loan to its purpose and the life of the asset", "Overdraft and cash credit are common working capital forms"], "source_url": null, "sort_order": 4},
{"id": "5e221f62-7265-5d15-98ad-c68b877923bf", "role": "credit-analyst", "kind": "role", "difficulty": "easy", "category": "Credit risk", "question": "What is the CIB report, and why do you check it before lending?", "key_points": ["A report from Bangladesh Bank's credit information bureau on a borrower's loans", "Shows existing loans, repayment history and any classified loans", "A bad record or hidden loans are warning signs", "Check the owners and related companies too"], "source_url": "https://www.bb.org.bd/", "sort_order": 5},
{"id": "1135020a-3783-57a8-9d70-e929c997ffcb", "role": "credit-analyst", "kind": "role", "difficulty": "medium", "category": "Cash flow", "question": "A company shows good profit but always has cash problems. What could be the reasons?", "key_points": ["Customers pay slowly, so receivables keep growing", "Too much stock, or stock that does not sell", "Profit spent on big assets or taken out by the owners", "Short-term loans used to pay for long-term assets"], "source_url": null, "sort_order": 6},
{"id": "d5102be1-2d46-593d-baa2-5e59ecd85a01", "role": "credit-analyst", "kind": "role", "difficulty": "medium", "category": "Collateral", "question": "A borrower offers land as collateral. What do you check?", "key_points": ["Ownership papers: title deed, mutation and khatian, and the chain of past deeds", "Other mortgages or disputes, and that the land matches the papers", "An independent valuation with a realistic forced-sale value", "A properly registered mortgage, with insurance where needed"], "source_url": null, "sort_order": 7},
{"id": "39e74f9b-2483-5da5-a043-d00b2042df67", "role": "credit-analyst", "kind": "role", "difficulty": "medium", "category": "Ratios", "question": "What is the debt service coverage ratio, and why do lenders use it?", "key_points": ["Cash available for repayments divided by the loan payments due", "Shows if the business can pay its instalments from its own cash", "Below one means operations cannot cover the payments", "Test it under a bad year as well"], "source_url": null, "sort_order": 8},
{"id": "942ab0f4-57be-553c-8acd-c984c0b088a3", "role": "credit-analyst", "kind": "role", "difficulty": "medium", "category": "Loan types", "question": "How does a letter of credit help an importer, and what risk does the bank take?", "key_points": ["The bank promises to pay the seller if the documents match the terms", "The importer gets goods without paying in advance", "The bank risks the importer not paying when the bill falls due", "Check the importer's track record, margin and the goods' value"], "source_url": null, "sort_order": 9},
{"id": "44446d47-5a6d-514f-851b-e66a4f7fa1b7", "role": "credit-analyst", "kind": "role", "difficulty": "medium", "category": "Report writing", "question": "What goes into a credit memo for an approval committee?", "key_points": ["Borrower background, purpose and amount asked", "Financial analysis: trends, ratios and cash flow", "Risks, how they are reduced, and the collateral", "A clear recommendation with conditions"], "source_url": null, "sort_order": 10},
{"id": "e52fda53-e53c-59fe-98c8-ddf4fec1cf14", "role": "credit-analyst", "kind": "role", "difficulty": "hard", "category": "Credit risk", "question": "An SME owner has no audited accounts, only handwritten records and bank statements. How would you assess the loan?", "key_points": ["Rebuild cash flow from bank statements, sales records and site visits", "Visit the business: stock, customers and suppliers", "Check the owner's record, the credit report and references", "Start with a smaller limit and close monitoring"], "source_url": null, "sort_order": 11},
{"id": "383e915c-767e-57b8-8eb3-016418389b61", "role": "credit-analyst", "kind": "role", "difficulty": "hard", "category": "Cash flow", "question": "A garment exporter's main buyer has cut orders, and the company asks to extend its loan. What do you look at?", "key_points": ["How much of sales came from that buyer, and new orders in hand", "An updated cash flow forecast under a realistic case", "Options: reschedule with conditions, more security, or lower exposure", "Follow the bank's policy and Bangladesh Bank rules on rescheduling"], "source_url": "https://www.bb.org.bd/", "sort_order": 12},
{"id": "84f430d5-0c51-59c1-8f32-0851ec5cccc0", "role": "credit-analyst", "kind": "role", "difficulty": "hard", "category": "Financial statements", "question": "The sales in a borrower's financial statements are much higher than in their bank statements and VAT returns. What do you do?", "key_points": ["Treat the gap as a sign the numbers may be inflated", "Ask the borrower to explain, with documents", "Base the analysis on figures you can verify", "Report the gap clearly in the credit memo"], "source_url": "https://nbr.gov.bd/", "sort_order": 13},
{"id": "92400b0f-ce05-5fb3-ba49-51c09ee10a71", "role": "credit-analyst", "kind": "role", "difficulty": "hard", "category": "Collateral", "question": "Why should a loan never be approved just because the collateral is strong?", "key_points": ["Collateral is the second way out; cash flow is the first", "Selling land or property through the courts can take years", "Values can fall and papers can have problems", "A good loan is repaid by the business, not by selling security"], "source_url": null, "sort_order": 14},
{"id": "e04f12a4-8d7a-5f77-a152-f3013d28417f", "role": "credit-analyst", "kind": "role", "difficulty": "hard", "category": "Report writing", "question": "Your manager wants to approve a loan for a big client, but your analysis shows weak cash flow. What do you do?", "key_points": ["Present the facts and numbers clearly and calmly", "Suggest ways to lower risk: a smaller amount, more security, covenants", "Write your view in the memo, even if you are overruled", "Never change the analysis to fit the decision"], "source_url": null, "sort_order": 15},
